join (values ('Other', 'Korean Zen (180 min)', 'Start in the steam. Then the Korean scrub — the real kind that removes weeks of dead skin in minutes. Bubble massage, hair wash, Balinese massage, and facial follow. You''ll walk out looking and feeling like a new person.', 1200000, 'IDR', 0), ('Other', 'Korean Zen (180 min)', 'Start in the steam. Then the Korean scrub — the real kind that removes weeks of dead skin in minutes. Bubble massage, hair wash, Balinese massage, and facial follow. You''ll walk out looking and feeling like a new person.', 1200000, 'IDR', 1), ('Hammam', 'Hammam Adventure (180 min)', 'Ubud''s take on the Turkish bath. Facilities, scrub, bubble massage, hair wash, reflexology, Balinese massage, and a natural facial. Three hours that leave you completely reset.', 1200000, 'IDR', 0), ('Hammam', 'Hammam Adventure (180 min)', 'Ubud''s take on the Turkish bath. Facilities, scrub, bubble massage, hair wash, reflexology, Balinese massage, and a natural facial. Three hours that leave you completely reset.', 1200000, 'IDR', 1), ('Balinese Massage', 'Balinese Bliss (180 min)', 'Bali''s own tradition, done right. Boreh spice scrub, bubble massage, Balinese massage, and a closing facial. Ancient ingredients, expert hands, and a glow that lasts days.', 1200000, 'IDR', 0), ('Balinese Massage', 'Balinese Bliss (180 min)', 'Bali''s own tradition, done right. Boreh spice scrub, bubble massage, Balinese massage, and a closing facial. Ancient ingredients, expert hands, and a glow that lasts days.', 1200000, 'IDR', 1), ('Balinese Massage', 'Balinese Massage (90 min)', null, 600000, 'IDR', 2), ('Body Scrub', 'Korean Scrub (90 min)', null, 600000, 'IDR', 0), ('Aromatherapy', 'Aromatherapy (90 min)', null, 600000, 'IDR', 0), ('Hot Stone', 'Hot Stone (120 min)', null, 600000, 'IDR', 0), ('Thai Massage', 'Thai Massage (90 min)', null, 600000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue (90 min)', null, 600000, 'IDR', 0), ('Balinese Boreh', 'Boreh (90 min)', null, 600000, 'ID