join (values ('Traditional Massage', 'Ubud Royal Massage (60 min)', 'A massage fit for the Ubud Royal Family. Two therapists, working simultaneously will provide you with a blissful experience. Combining different massage techniques, you will end the massage feeling peaceful and relaxed.', 520000, 'IDR', 0), ('Traditional Massage', 'Ubud Royal Massage (90 min)', 'A massage fit for the Ubud Royal Family. Two therapists, working simultaneously will provide you with a blissful experience. Combining different massage techniques, you will end the massage feeling peaceful and relaxed.', 760000, 'IDR', 1), ('Traditional Massage', 'Rice Farmer Massage (60 min)', 'Based on the traditional massage given to the rice farmer by his wife after a long day in the field. Your therapist will utilize their lower arms and elbows to provide deep pressure on your sore muscles. Perfect for when your body needs extra relief!', 310000, 'IDR', 2), ('Traditional Massage', 'Rice Farmer Massage (90 min)', 'Based on the traditional massage given to the rice farmer by his wife after a long day in the field. Your therapist will utilize their lower arms and elbows to provide deep pressure on your sore muscles. Perfect for when your body needs extra relief!', 430000, 'IDR', 3), ('Traditional Massage', 'Bali Traditional Massage (60 min)', 'Our traditional Balinese style massage uses palm pressure on your body with long, stretching and sweeping movements for deep relaxation. Your massage can be from gentle to strong; the choice is up to you.', 280000, 'IDR', 4), ('Traditional Massage', 'Bali Traditional Massage (90 min)', 'Our traditional Balinese style massage uses palm pressure on your body with long, stretching and sweeping movements for deep relaxation. Your massage can be from gentle to strong; the choice is up to you.', 400000, 'IDR', 5), ('Traditional Massage', 'Rice Farmer Massage (90 min)', 'Inspired by the traditional techniques of Bali farmers, providing a great relax.', 350000, 'IDR', 6), ('Reflexology', 'Balinese Reflexology (60 min)', 'If your feet and legs are tired from exploring Bali, our reflexology treatment will help you regain your strength. Our therapist will stimulate the reflex points in the feet and lower legs, using both the strength of their hands and a wooden dowel.', 260000, 'IDR', 0), ('Reflexology', 'Balinese Reflexology (30 min)', 'If your feet and legs are tired from exploring Bali, our reflexology treatment will help you regain your strength. Our therapist will stimulate the reflex points in the feet and lower legs, using both the strength of their hands and a wooden dowel.', 150000, 'IDR', 1), ('Balinese Massage', 'Traditional Balinese Massage (60 min)', 'A popular traditional massage technique that combines acupressure and gentle stretches.', 250000, 'IDR', 0), ('Couple Massage', 'Couples Massage (60 min)', 'Experience the massage treatment together in the same room.', 500000, 'IDR', 0), ('Flower Bath', 'Body Scrub & Flower Bath (60 min)', 'Exfoliates and relaxes your skin, followed by a soothing flower bath.', 300000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

