from m, secs
join (values ('Traditional Massage', 'BALINESE HEALING MASSAGE (60 min)', 'Gentle to medium pressure is applied in this traditional Balinese technique that combines long strokes, skin folding and kneading. It is deeply soothing and restoring. Choose between Sensatia Relaxation or Seaside Citrus Massage Oil.', 300000, 'IDR', 0), ('Traditional Massage', 'BALINESE HEALING MASSAGE (90 min)', 'Gentle to medium pressure is applied in this traditional Balinese technique that combines long strokes, skin folding and kneading. It is deeply soothing and restoring. Choose between Sensatia Relaxation or Seaside Citrus Massage Oil.', 420000, 'IDR', 1), ('Traditional Massage', 'SPIRAL SPA MASSAGE (60 min)', 'Created specially to relax the whole body and increase blood circulation to the skin and muscles. Using warm Sensatia Lemongrass & Mandarin Massage Oil, medium to strong pressure is applied to dissolve muscle tightness and calm the nervous system.', 325000, 'IDR', 2), ('Traditional Massage', 'SPIRAL SPA MASSAGE (90 min)', 'Created specially to relax the whole body and increase blood circulation to the skin and muscles. Using warm Sensatia Lemongrass & Mandarin Massage Oil, medium to strong pressure is applied to dissolve muscle tightness and calm the nervous system.', 445000, 'IDR', 3), ('Hot Stone', 'HOT STONES MASSAGE (60 min)', 'Recommended for back pain or headaches caused by muscle tensions in the neck and upper back. The combination of heat and massage penetrates deeply and releases tensions.', 350000, 'IDR', 0), ('Lomi Lomi', 'LOMI LOMI MASSAGE (60 min)', 'This deep tissue massage is originally from Hawaii, a combination of elbow and knuckle movement which allows the therapist to apply a strong pressure. Uses Sensatia Lemongrass & Mandarin Massage Oil.', 350000, 'IDR', 0), ('Reflexology', 'REFLEXOLOGY FOOT MASSAGE (60 min)', 'Hand, thumb and finger techniques stimulate certain areas of the feet. Sensatia Seaside Citrus Body Butter is used.', 285000, 'IDR', 0), ('Head Massage', 'DE-STRES HEAD AND SHOULDERS MASSAGE (45 min)', 'Relieve tensions and headaches on your upper body.', 235000, 'IDR', 0), ('Other', 'JET LAG COMBAT (60 min)', 'Back and leg massage to provide relaxation after your long journey.', 300000, 'IDR', 0), ('Other', 'AFTER SUN (30 min)', 'Specially formulated for sun-exposed skin, Sensatia Dream Cream contains a blend of pure plant compounds that soften, moisturize and cool the skin.', 180000, 'IDR', 1), ('Foot Massage', 'EXPRESS FOOT MASSAGE (30 min)', 'Relaxing massage for tired feet.', 180000, 'IDR', 0), ('Javanese Lulur', 'TRADITIONAL JAVANESE LULUR (45 min)', 'Blend of turmeric, sandalwood, jasmine flower, pandanus leaf and ground rice are the base of this exfoliating treatment that leaves the skin smooth and soft.', 230000, 'IDR', 0), ('Body Scrub', 'SEA SALT BODY SCRUB (45 min)', 'Buff away impurities with this blend of pure Balinese sea salt, orange extract and lemongrass essential oil. Uses Sensatia Seaside Citrus Sea Salt Scrub.', 250000, 'IDR', 0), ('Facial', 'REJUVENATING FACIAL (60 min)', 'Six steps to leave your face radiantly refreshed:

1. Facial Cleanser (blend of rose petals, geranium and hibiscus extracts).
2. Facial Scrub (argan seeds and shea butter).
3. Facial Hydrate (rosehip oil and olive squalane).
4. Facial Mask (essential oil of rose and strawberry extracts).
5. Facial Toner (non-alcohol formula and aloe vera extracts).
6. Facial C-Serum blossom facial dream cream.', 365000, 'IDR', 0), ('Facial', 'BALINESE HEALING MASSAGE + REJUVENATING FACIAL (120 min)', null, 600000, 'IDR', 1), ('Hair Treatment', 'REVITALIZING HAIR MASK (60 min)', 'An intensive treatment for the hair and scalp. After washing with Sensatia Nurturing Shampoo, Argan & Tamarind Revitalizing Hair Mask is massaged into wet hair. A 15 minute hand and neck massage follows while the hair is wrapped in a warm towel. After rinsing, shampooing and conditioning Nurturing Hair Oil is massaged into scalp and hair for extra lustre.', 300000, 'IDR', 0), ('Hair Treatment', 'SPIRAL SPA MASSAGE + REVITALIZING HAIR MASK (120 min)', null, 575000, 'IDR', 1), ('Hair Styling', 'HAIR WASH EXPRESS (30 min)', 'Using Sensatia Nurturing Shampoo and Conditioner for soft, shiny and full body hair. Contains botanical extracts, lemon oil and marshmallow root extract that soothes the scalp and helps smooth tangles.', 150000, 'IDR', 0), ('Manicure', 'COMPLETE MANICURE (60 min)', 'Nail filing, shaping and cuticle treatment combined with a relaxing hand massage. Nail polish application is included.', 260000, 'IDR', 0), ('Manicure', 'EXPRESS MANICURE (30 min)', 'Nail filing, shaping and cuticle treatment. Nail polish application is included.', 180000, 'IDR', 1), ('Pedicure', 'COMPLETE PEDICURE (60 min)', 'A cleansing foot soaking bath is followed by toenail filing, shaping and cuticle treatment and exfoliation of dead skin cells. Finally a moisturizing foot massage to leave the feet like new. Nail polish application is included.', 275000, 'IDR', 0), ('Pedicure', 'EXPRESS PEDICURE (30 min)', 'Toenail grooming including filing, shaping and cuticle treatment. Nail polish application is included.', 180000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'thesamaya.com' and status = 'active' and publication_status = 'published' and category in ('spa', 'beauty', 'yoga', 'fitness') order by case category when 'spa' then 0 when 'beauty' then 1 else 2 end, slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'The Samaya Ubud-Bali treatment prices',
         coalesce((select max(mx.version) from menus mx where mx.venue_slug = t.slug), 0) + 1,
         'draft', 'partial', 'https://thesamaya.com/lumonata-plugins/custom-post/pdf/spa-menu-the-samaya-ubud-1751273163.pdf', 'Official The Samaya Ubud-Bali price list',
         '2026-08-25T05:28:30+00:00'::timestamptz, null, '2026-11-23T05:28:30+00:00'::timestamptz, '6ae09b86318e891a5e1e73f8db260e5118db1a19dec141d64bfebf4e2d7f229e', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug
                    and x.status in ('source_snapshot', 'published'))
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Balinese Massage', 0), ('Couple Massage', 1), ('Aromatherapy', 2), ('Facial', 3), ('Traditional Massage', 4), ('Other', 5)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Balinese Massage', 'Single Balinese Massage (60 min)', 'A traditional Balinese therapy combining stretching, long strokes, skin rolling, and palm and thumb pressure techniques to relieve tension and improve blood flow.', 550000, 'IDR', 0), ('Balinese Massage', 'Balinese Eternal Bliss (150 min)', 'This Ritual begins with Samaya foot ritual to enchange your foot wash, aroma warm oil massage with petal roses choice of royal Javanese lulur or Balinese boreh hot spicy body mask. Tea ceremony while enjoyed jacuzzi qith aroma of milk bath. fresh traditional facial, Samaya body lotion to moisture your skin.', 1300000, 'IDR', 1), ('Balinese Massage', 'Balinese Journey of Joy (120 min)', 'This ritual begins with Samaya foot ritual to enchance your foot wash, Aroma warm oil massage with petal roses, green tea body scrub to leaves your skin soft and silky. Green tea body mask which promotes and re-generation your skin. White roses milk bath while enjoyed tea ceremony. Samaya body lotion to moisture your skin.', 1100000, 'IDR', 2), ('Balinese Massage', 'Balinese Massage (60 min)', 'Used for centuries to renew, strengthen and heal the body, this traditional Balinese therapy combines stretching, long strokes, skin rolling, and palm and thumb pressure techniques commonly used in village massage. A flowing and graceful massage to relieve tension, improve blood flow and ease stress.', 550000, 'IDR', 3), ('Couple Massage', 'Couple Balinese Massage (60 min)', 'A traditional Balinese therapy combining stretching, long strokes, skin rolling, and palm and thumb pressure techniques to relieve tension and improve blood flow.', 750000, 'IDR', 0), ('Aromatherapy', 'Aroma Hot Stone Therapy (60 min)', 'Therapeutic treatment designed to relieve stiffness and soreness using smooth, warmed river rocks gliding across the body.', 600000, 'IDR', 0), ('Facial', 'Traditional Facial (60 min)', 'Merging modern techniques with ancient Asian beauty rituals for a lasting impression and instant benefits.', 500000, 'IDR', 0), ('Facial', 'Mini Facial (For Junior Guest 4-10 Years Old) (30 min)', 'Refreshing facial that includes thorough cleansing with creamy yogurt and blissful massage.', 250000, 'IDR', 1), ('Facial', 'Pure Essential Facial (60 min)', 'Balancing facial experience using organic aromatherapy elixirs & botanical actives to purify and renew the skin.', 900000, 'IDR', 2), ('Traditional Massage', 'Comfort Massage (30 min)', 'A gentle relaxing massage starting with Samaya foot ritual.', 250000, 'IDR', 0), ('Other', 'Coconut in Paradise (150 min)', 'This Ritual begins with Samaya foot ritual to enchange your foot wash, a choice of oriental massage or balinese massage with 100% virgin coconut oil. Head massage using coconut oil infused with rosemary. continue with coconut hair mask application, freshly ground coconut -vanilla body polish, coconut & pandan juice ceremony while enjoyed balinese five flowers and coconut milk bath. coconut lotion ', 1250000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

