insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Deep Tissue', 'Deep Tissue – Karsa Spa’s signature massage (60 min)', 'A thorough massage based on Chinese acupressure points to release stress and blockages from the tips of your toes to the top of your head. It helps to loosen muscle tissues, release toxins from muscles and get blood and oxygen circulating properly. Our deep tissue massage is beneficial for many physical problems, including sports injuries and chronic pain. You will be kneaded, pressed, stretched, ', 260000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue – Karsa Spa’s signature massage (90 min)', 'A thorough massage based on Chinese acupressure points to release stress and blockages from the tips of your toes to the top of your head. It helps to loosen muscle tissues, release toxins from muscles and get blood and oxygen circulating properly. Our deep tissue massage is beneficial for many physical problems, including sports injuries and chronic pain. You will be kneaded, pressed, stretched, ', 380000, 'IDR', 1), ('Balinese Massage', 'Traditional Balinese (60 min)', 'Traditional Balinese techniques that include long strokes and light acupressure stimulation. Releases muscle tension, improves blood circulation and dissolves stress. Try and stay awake to saviour this treat!', 240000, 'IDR', 0), ('Balinese Massage', 'Traditional Balinese (90 min)', 'Traditional Balinese techniques that include long strokes and light acupressure stimulation. Releases muscle tension, improves blood circulation and dissolves stress. Try and stay awake to saviour this treat!', 350000, 'IDR', 1), ('Traditional Massage', 'Intuitive Heart Massage (90 min)', 'Your massage begins with Reiki which opens your aura and chakras to receive divine healing energy throughout your treatment. Reiki also brings your therapist into their highest state so they are totally present and focused on you and your experience. Your massage flows seamlessly as your therapist tunes into your body and hones into areas that require extra attention. Techniques used include Balin', 400000, 'IDR', 0), ('Traditional Massage', 'Anak Anak Kids Massage (30 min)', 'A lovely introduction to bodywork for your wriggling, giggling little ones. We will go with the flow and are flexible to ensure they have a fun, positive experience.', 140000, 'IDR', 1), ('Traditional Massage', 'Anak Anak Kids Massage (60 min)', 'A lovely introduction to bodywork for your wriggling, giggling little ones. We will go with the flow and are flexible to ensure they have a fun, positive experience.', 240000, 'IDR', 2), ('Shiatsu', 'Shiatsu Treatment (60 min)', 'A massage based on ancient Japanese healing systems to release muscle and meridian blockages which may cause pain physically, mentally and emotionally. Your therapist works deeply, without oil. Techniques used include acupressure with thumbs, palms, elbows, and the occasional foot! Only with our male therapists. This style of massage can be fully clothed if you prefer.', 280000, 'IDR', 0), ('Shiatsu', 'Shiatsu Treatment (90 min)', 'A massage based on ancient Japanese healing systems to release muscle and meridian blockages which may cause pain physically, mentally and emotionally. Your therapist works deeply, without oil. Techniques used include acupressure with thumbs, palms, elbows, and the occasional foot! Only with our male therapists. This style of massage can be fully clothed if you prefer.', 400000, 'IDR', 1), ('Sports Massage', 'Therapeutic / Sports Massage (90 min)', 'This massage is with an experienced male therapist for injuries or long term problems that you just can’t seem to shift. Inform your therapist where and how you received your injury and they will concentrate on this area with a combination of trigger point therapy, deep tissue, Shiatsu, Reiki and other relaxing techniques.', 450000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (30 min)', 'Acupressure points on your feet correspond with body organs and parts of your body. When stimulated many blockages are released and dissolved. Where are your sore spots? Let your therapist soothe and nurture your body and sole! First we wash your feet, then treat you to a fantastic foot and lower leg reflexology massage. Finally we clean you up, revive you with our magic peppermint spray and send ', 140000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (60 min)', 'Acupressure points on your feet correspond with body organs and parts of your body. When stimulated many blockages are released and dissolved. Where are your sore spots? Let your therapist soothe and nurture your body and sole! First we wash your feet, then treat you to a fantastic foot and lower leg reflexology massage. Finally we clean you up, revive you with our magic peppermint spray and send ', 260000, 'IDR', 1), ('Thai Massage', 'Thai Yoga Massage (90 min)', 'Yoga without the effort! A gentle form of Thai massage on a floor mat. Our male therapists only have been trained in this beautiful technique. You are given Thai pants and a tshirt to wear as this massage has a lot of body contact between therapist and client. Your therapist uses his thumbs, palms, forearms, feet, knees and torso to press and stretch your body. He uses slow rhythmic movements to r', 450000, 'IDR', 0), ('Neck & Shoulder', 'Back Neck Shoulder Massage (30 min)', 'A deep tissue massage without the limbs for those in a hurry or who need more back neck shoulder focus. This massage can be had sitting in a chair through your clothes (shiatsu style massage) or on a massage table with oil. For strong massage please request a male therapist.', 150000, 'IDR', 0), ('Neck & Shoulder', 'Back Neck Shoulder Massage (60 min)', 'A deep tissue massage without the limbs for those in a hurry or who need more back neck shoulder focus. This massage can be had sitting in a chair through your clothes (shiatsu style massage) or on a massage table with oil. For strong massage please request a male therapist.', 280000, 'IDR', 1), ('Pregnancy Massage', 'Baby on Board Pregnancy Massage (60 min)', 'Massage at an angle, according to your individual needs. You can choose to be sitting in a chair or lying on a table. We support you with plenty of cushions and bolsters so you can relax and drift away to whatever Nirvana calls to you today……. relief on weight bearing joints such as ankles, lower back and pelvis. reduced swelling in hands and feet. lessens sciatica pain, fewer calf cramps. Increas', 240000, 'IDR', 0), ('Pregnancy Massage', 'Baby on Board Pregnancy Massage (90 min)', 'Massage at an angle, according to your individual needs. You can choose to be sitting in a chair or lying on a table. We support you with plenty of cushions and bolsters so you can relax and drift away to whatever Nirvana calls to you today……. relief on weight bearing joints such as ankles, lower back and pelvis. reduced swelling in hands and feet. lessens sciatica pain, fewer calf cramps. Increas', 350000, 'IDR', 1), ('Other', 'Singing Bowl Healing Vibration (30 min)', 'Two beautiful big singing bowls forged under a full moon in Nepal have found their new home at Karsa Spa. Our male therapists have learned to work with the vibratory energies of the bowls as an add on treatment at the end of your massage. The bowl is placed over energy centres and acupressure points on your back, shoulders, legs and feet then struck as well as rubbed, to produce 2 different types ', 140000, 'IDR', 0), ('Other', 'Hair Creambath (60 min)', 'We shampoo your hair with our green tea shampoo, then apply a deeply nourishing hair mask treatment that contains candlenut oil. Enjoy a deep scalp massage then we wrap your hair in a hot towel and massage your neck, shoulders and arms', 240000, 'IDR', 1), ('Other', 'Shampoo only (60 min)', 'Shampoo only', 120000, 'IDR', 2), ('Other', 'Cooling cucumber aloe sunburn soother (90 min)', 'We apply a blend of soothing aloe vera and cucumber paste onto your sunburn before gently massaging using acupressure techniques. Aloe vera is renowned for it’s cooling qualities and is used extensively in healing and moisturising skin damaged by sun exposure. A tepid flower bath to linger in completes this cooling treatment.', 400000, 'IDR', 3), ('Other', 'Bath (30 min)', 'Add any bath after a massage or treatment.', 150000, 'IDR', 4), ('Other', 'Bath (30 min)', 'Add any bath after a massage or treatment.', 250000, 'IDR', 5), ('Cupping', 'Chinese Cupping (30 min)', 'Cupping at Karsa Spa involves placing modern, silicone cups on the skin and creating a vacuum by suctioning out the air. The suction in the cups causes the skin and superficial muscle layer to be lightly drawn into the cup. Cupping is much like the inverse of massage – rather than applying pressure to muscles, it uses gentle pressure to pull them upward. This is usually a deeply relaxing and relie', 140000, 'IDR', 0), ('Facial', 'Organic honey and carrot facial (60 min)', 'Cleanse and exfoliate with carrot and yoghurt combinations, followed by a delicious warm honey massage. Next an organic mask is applied, containing sacred volcanic clay. Slices of cucumber are laid over your eyes so you can drift away and enjoy a hand and foot massage whilst your mask does its work. Finally we apply a natural moisturiser. Your skin feels soft, refreshed and alive.', 240000, 'IDR', 0), ('Facial', 'Biokos Facial (60 min)', 'Biokos is a range of Indonesian pharmaceutical facial products. Not completely organic, but do a fantastic job of cleansing, exfoliating, toning and moisturising your face. And they smell great. Your choice of our aloe vera or seaweed range.', 240000, 'IDR', 1), ('Manicure', 'Manicure with OPI products (60 min)', 'After a warm hand bath and soak your therapist will cleanse, trim, shape, buff and beautify your nails and cuticles. Polish of your choice is applied and you are indulged with a delicious arm and hand acupressure massage. Be assured that all our manicure and pedicure tools are sanitised between customers.', 220000, 'IDR', 0), ('Manicure', 'Manicure with OPI products (60 min)', '1 Hour French Manicure', 240000, 'IDR', 1), ('Manicure', 'Manicure with OPI products (60 min)', '1 Hour Manicure with Nail Art', 270000, 'IDR', 2), ('Pedicure', 'Pedicure with OPI products (60 min)', 'A well-deserved pampering, and essential for getting your toes and heels looking and feeling healthy. Your treatment includes a foot reflexology massage to relieve exhausted feet and is a divine way to chill out after trekking the ridge or shopping in Ubud all day. We begin with a foot scrub, then get down to the business of gently removing dry skin and callouses before trimming and shaping your n', 220000, 'IDR', 0), ('Pedicure', 'Pedicure with OPI products (60 min)', '1 Hour French Pedicure', 240000, 'IDR', 1), ('Pedicure', 'Pedicure with OPI products (60 min)', '1 Hour Predicure with Nail Art', 270000, 'IDR', 2), ('Ear Candle', 'Ear Candling (30 min)', 'Ear candling involves inserting a long, cylindrical candle into the ear and lighting it on the other end. Heat produced from the candle helps draw out excess ear wax and other debris which may be present in the ear canal. Benefits of ear candling may include relieving tinnitus (ringing in the ears), helping to relieve sinus pain and pressure, removing excess wax build up, assisting with relieving ', 140000, 'IDR', 0), ('Balinese Boreh', 'Spicy Balinese Boreh (120 min)', 'First we indulge you with a 60 minute Balinese massage with our warm Ayurvedic oil blend. Next we exfoliate with a traditional spice blend of cloves, ginger, nutmeg, cinnamon, ground rice and coriander. We leave you wrapped cosily in a sarong for a few minutes whilst the spices work their magic and seep warmth into your bones. We wash you off with warm water and a mask of fresh tamarind and pure B', 480000, 'IDR', 0), ('Javanese Lulur', 'Lulur Vegan Delight (120 min)', 'A nurturing Balinese massage for 60 minutes followed by a traditional Indonesian Lulur exfoliation scrub consisting of turmeric, coriander, red rice, evgania and essential oils. Next a sacred clay body mask is rubbed into your skin to tone, soften, and moisturise. Finally you float from the table into a hot flower bath.', 480000, 'IDR', 0), ('Body Scrub', 'Ayuvedic Healing or Coffee Salt Scrub (120 min)', 'A tranquil Balinese massage for an hour is followed by a reviving Ayuvedic Healing or Coffee salt scrub. Salt is a great way to exfoliate dead skin cells. This paves the way for fresh new cells to regenerate and leaves you looking and feeling fabulous. Coffee grounds are the best option for use on cellulite prone areas of the body, as well as leaving you with a radiant caffeine fueled glow. We the', 480000, 'IDR', 0), ('Body Scrub', 'Scrub and Bath (60 min)', 'After any massage add on any scrub and bath combination: 1. Balinese Boreh with tamarind honey mask followed by your choice of bath (see options below) 2. Lulur Scrub with sacred clay body mask followed by your choice of bath 3. Salt scrub with yoghurt body mask followed by your choice of bath', 250000, 'IDR', 1), ('Reiki', 'Reiki Healing (60 min)', 'A full Reiki treatment from the top of your head to the soles of your feet, front and back of your body is followed by Reiki focused on your specific problem area to encourage healing at many levels.', 280000, 'IDR', 0), ('Reiki', 'Reiki Healing (30 min)', 'A full Reiki treatment from the top of your head to the soles of your feet, front and back of your body is followed by Reiki focused on your specific problem area to encourage healing at many levels.', 140000, 'IDR', 1), ('Reiki', 'Reiki Chakra Balance (30 min)', 'Chakras are the energy centres in our bodies that spin and distribute our prana / chi / essential life force. These centres get clogged up over time when we experience stress and negative emotions. We cleanse each of your 7 individual chakras, releasing blockage and negativity. Finally we balance your key chakra centres in relation to their corresponding chakra. We also use coloured crystals over ', 140000, 'IDR', 2), ('Spa Package', 'Buddha Package (300 min)', 'Two & half hours of healing. The following is a list of treatments that we will provide : Your choice of 1 of the following 60 minute massages – Balinese Massage – Foot Reflexology Organic Facial (60 mins) or Hair Creambath (60 mins) Chakra Balance (30 mins)', 600000, 'IDR', 0), ('Spa Package', 'Saraswati Package (240 min)', '4 hours of divine nurturing to release your inner Goddess or warrior. The following is a list of treatments that we will provide : Manicure or Pedicure (60 mins) 75 minute Intuitive Heart Massage followed by your choice of body scrub and bath combination (2 hours) Organic Facial (60 mins) or Hair Creambath (60 mins)', 950000, 'IDR', 1), ('Spa Package', 'All day transformation Package (360 min)', 'This package treatment take time 6 hours start from 10am – 5pm. The following is a list of treatments that we will provide : Foot reflexology (60 mins) Manicure or Pedicure (60 mins) Reiki Healing (60 mins) Lunch break at nearby Karsa Kafe (package price does not include lunch) 75 minute Intuitive Heart Massage followed by your choice of body scrub & bath combination (2 hours) Organic Facial (60 m', 1450000, 'IDR', 2)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

