with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'sangspa.com' and status = 'active' and publication_status = 'published' and category in ('spa', 'beauty', 'yoga', 'fitness') order by case category when 'spa' then 0 when 'beauty' then 1 else 2 end, slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Sang Spa treatment prices',
         coalesce((select max(mx.version) from menus mx where mx.venue_slug = t.slug), 0) + 1,
         'draft', 'partial', 'https://sangspa.com/', 'Official Sang Spa price list',
         '2026-08-25T05:28:30+00:00'::timestamptz, null, '2026-11-23T05:28:30+00:00'::timestamptz, '863be21b551d0d70146a6f2a54f31ba7122e556f0ed3ef6264b4fc794e6a3bb3', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug
                    and x.status in ('source_snapshot', 'published'))
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Couple Massage', 0), ('Balinese Massage', 1), ('Body Scrub', 2), ('Spa Package', 3), ('Traditional Massage', 4), ('Other', 5)) as s(name, pos)
