join (values ('Reflexology', 'COZY FOOT Reflexology (60 min)', 'Famous as COZY''s best treatment, must try. Good pressure and COZY''s deep relaxing technique. Hand, Neck and Shoulder Massage.', 170375, 'IDR', 0), ('Reflexology', 'COZY Body Reflexology (90 min)', 'No oil, no body butter, just deep pressure and expert techniques to reset your body.', 311375, 'IDR', 1), ('Reflexology', 'COZY FOOT Reflexology (60 min)', 'Famous as COZY''s best treatment, must try. Good pressure and COZY''s deep relaxing technique. Hand, Neck and Shoulder Massage. YOU''LL love it.', 170375, 'IDR', 2), ('Reflexology', 'COZY Body Reflexology (90 min)', 'No oil, no body butter, just deep pressure and expert techniques to release tight muscles, melt away tension, and recharge your body. Feel the pressure. Free the tension. Reset.', 311375, 'IDR', 3), ('Traditional Massage', 'COZY Body Massage Sensation (60 min)', 'Our full body massage collection. From the rhythmic Swedish & Javanese strokes of COZY Me to the deep Balinese & Lomi Lomi release of COZY Dream.', 252625, 'IDR', 0), ('Traditional Massage', 'COZY Body Massage Sensation (60 min)', 'Our full body massage collection. From the rhythmic Swedish & Javanese strokes of COZY Me, to the deep Balinese & Lomi Lomi release of COZY Dream, the all-senses journey of Take Me To The Moon, and the focused deep pressure of Release Sport Massage — find the perfect touch for your body.', 252625, 'IDR', 1), ('Head Massage', 'COZY Head Massage (60 min)', 'Surrender to deep relaxation with our head-focused therapies. Include soothing hand & foot massage.', 240875, 'IDR', 0), ('Head Massage', 'COZY Head Massage (60 min)', 'Surrender to deep relaxation with our head-focused therapies. COZY Scalp Sensation nourishes your scalp with a creambath-style treatment, while COZY Shiatsu uses olive oil and precision pressure points to melt away tension. Both include soothing hand & foot massage.', 240875, 'IDR', 1), ('Other', 'COZY Cozy & COZY Delight (90 min)', 'Two treatments, two skilled therapists, working together in perfect harmony.', 458250, 'IDR', 0), ('Other', 'COZY You Feel (90 min)', 'A complete head-to-toe renewal. Tension dissolves as your skin is exfoliated and deeply nourished.', 381875, 'IDR', 1), ('Other', 'COZY Back Pleasure Therapy (60 min)', 'A specialized treatment for tired shoulders, stiff backs, and tense waist & hips.', 311375, 'IDR', 2), ('Other', 'COZY Cozy & COZY Delight (90 min)', 'Two treatments, two skilled therapists, working together in perfect harmony. A synchronized experience that makes 90 minutes truly the best time to relax, rejuvenate, and unwind — an unforgettable feeling.', 458250, 'IDR', 3), ('Other', 'COZY You Feel (90 min)', 'A complete head-to-toe renewal. COZY massage meets a gentle full-body scrub for the ultimate pampering session. Tension dissolves as your skin is exfoliated and deeply nourished, leaving you feeling silky smooth and completely restored.', 381875, 'IDR', 4), ('Other', 'COZY Back Pleasure Therapy (60 min)', 'A specialized treatment for tired shoulders, stiff backs, and tense waist & hips—perfect for those who spend long hours sitting, working, or on the go. Skilled hands. Focused relief. Feel free. You always need this. Total back-body reset.', 311375, 'IDR', 5), ('Facial', 'COZY Refresh Me Up (Facial) (90 min)', 'Designed to relax, cleanse, tone and open the pores, these essential facials will refresh and revitalize your skin.', 365000, 'IDR', 0), ('Facial', 'COZY Refresh Me Up (Facial) (90 min)', 'Designed to relax, cleanse, tone and open the pores, these essential facials will refresh and revitalize your skin. Using Nu Skin products, suitable for Woman & Men skin''s type.', 365000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

