with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'bodyworshipbali.com' and status = 'active' and publication_status = 'published' and category in ('spa', 'beauty', 'yoga', 'fitness') order by case category when 'spa' then 0 when 'beauty' then 1 else 2 end, slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Body Worship Bali treatment prices',
         coalesce((select max(mx.version) from menus mx where mx.venue_slug = t.slug), 0) + 1,
         'draft', 'partial', 'https://bodyworshipbali.com/our-services/', 'Official Body Worship Bali price list',
         '2026-08-25T05:28:30+00:00'::timestamptz, null, '2026-11-23T05:28:30+00:00'::timestamptz, '18ef4ae951ab80fbf7937deb59c678d4b6dab60d13a91a58f3f1c5b6311d5ea2', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug
                    and x.status in ('source_snapshot', 'published'))
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Four Hands Massage', 0), ('Traditional Massage', 1), ('Aromatherapy', 2), ('Shiatsu', 3), ('Hot Stone', 4), ('Pregnancy Massage', 5), ('Balinese Massage', 6), ('Foot Massage', 7), ('Neck & Shoulder', 8), ('Other', 9), ('Hair Treatment', 10), ('Body Scrub', 11), ('Spa Package', 12), ('Hair Styling', 13), ('Facial', 14), ('Hydrating Facial', 15), ('Manicure', 16), ('Nails', 17), ('Pedicure', 18), ('Nail Art', 19)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
