join (values ('Manicure', 'Express Manicure (45 min)', 'This manicure will keep your hands and nails looking fabulous. Enjoy cuticle therapy and nail file before the finishing touch, a fresh polish application in your favourite colour.', 200000, 'IDR', 0), ('Manicure', 'Gel Polish Manicure or Gel Polish Pedicure (60 min)', 'An express manicure or pedicure including the application of quick-drying, chip-free, long lasting Shellac or The Perfect Match gel polish - providing a high gloss shine.', 365000, 'IDR', 1), ('Manicure', 'Dipping Powder Manicure (75 min)', 'Also known as SNS, this nail treatment uses a coloured powder to create a long-lasting and durable finish. This type of manicure is similar to Gel and quite resistant to chipping and fading.', 475000, 'IDR', 2), ('Manicure', 'BIAB – Builder (Gel) in a Bottle Manicure (75 min)', 'Experience this revolutionary nail treatment, designed for naturally stronger, longer nails. Our must-have builder gel creates a gentle yet resilient overlay, promoting nail health and encouraging natural growth for a flawless and longer lasting finish.', 520000, 'IDR', 3), ('Manicure', 'Kiddie Manicure (30 min)', null, 90000, 'IDR', 4), ('Pedicure', 'Express Pedicure (45 min)', 'This pedicure includes a brief callous removal, nail filing and shaping and finishing with a polish application in your favourite colour.', 235000, 'IDR', 0), ('Pedicure', 'Kiddie Pedicure (30 min)', null, 90000, 'IDR', 1), ('Other', 'Add-on Extra Callous Treatment (15 min)', null, 80000, 'IDR', 0), ('Other', 'Pretty Hands (70 min)', 'Indulge yourself in this lavish, premium hand treatment which includes cuticle therapy, a relaxing hand massage for circulation and parafin dip that leaves your hands irresistibly soft and smooth. The final touch is an expert polish application with the colour of your choice.', 330000, 'IDR', 1), ('Other', 'Happy Feet (70 min)', 'Our premium, results oriented pedicure treatment includes a smoothing exfoliation, thorough callous removal and a stimulating foot massage. This is followed by a cooling mint foot mask to soften, moisturise and freshen, then finished with an expert polish application with the colour of your choice.', 355000, 'IDR', 2), ('Other', 'Hard Gel / Acrylic Extensions - Full Set (120 min)', null, 650000, 'IDR', 3), ('Other', 'Hard Gel / Acrylic Extensions - Overlay', null, 630000, 'IDR', 4), ('Other', 'Hard Gel / Acrylic Extensions - Re-fill', null, 525000, 'IDR', 5), ('Other', 'Athena Microdermabrasion (45 min)', 'Our microdermabrasion facial by Athena is a non-surgical, non-chemical and non-invasive method of skin resurfacing.', 590000, 'IDR', 6), ('Other', 'Pro-Restore Microneedling by Dermalogica (90 min)', 'Rejuvenate your skin with Pro-Restore Microneedling by Dermalogica.', 1145000, 'IDR', 7), ('Other', 'Age Smart by Dermalogica (75 min)', 'Revitalise your skin with this powerful solution to help smooth away the signs of ageing.', 890000, 'IDR', 8), ('Other', 'Ultra Calming by Dermalogica (75 min)', 'Experience longer lasting relief from sensitive skin flare-ups, itching, sun burn or redness.', 760000, 'IDR', 9), ('Other', 'Island Indulgence (150 min)', 'Immerse yourself in the spirit of the island with this three-part indulgence.', 650000, 'IDR', 10), ('Other', 'Lost in Paradise', 'A truly unique Spa experience of indulgent proportions.', 1235000, 'IDR', 11), ('Other', 'RF Anti-Cellulite Treatment (120 min)', 'This non-invasive treatment harnesses radio-frequency (RF) technology to break down fat cells, restructure collagen fibers, and stimulate collagen production.', 900000, 'IDR', 12), ('Nails', 'Nail Extension Removal (30 min)', null, 170000, 'IDR', 0), ('Balinese Massage', 'Balinese Massage with Sand Compress (90 min)', 'Incorporating an oil blend massage and heated sand compress, this unique treatment combines traditional Balinese massage techniques to relieve muscle tension, stiffness, pain and fatigue.', 290000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue Massage (90 min)', 'This powerful healing and energizing massage uses pressure point, kneading and friction techniques to release deep muscle tension.', 290000, 'IDR', 0), ('Lymphatic Massage', 'Lymphatic Drainage Massage (75 min)', 'Our Lymphatic Drainage Massage uses the Vodder technique, a specialised approach that stimulates the lymphatic system, reduces inflammation and water retention, and enhances the immune system.', 410000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (30 min)', 'This foot therapy focuses on the feet to positively affect the whole body. Reflexology works on precise points on the feet that are believed to ‘reflex’ to other parts of the body.', 130000, 'IDR', 0), ('Traditional Massage', 'Therapeutic Massage (105 min)', 'Is there any specific area on your body where you feel the most pain? Maybe just your back or your legs?', 360000, 'IDR', 0), ('Body Scrub', 'Coconut Body Scrub (45 min)', null, 190000, 'IDR', 0), ('Facial', 'Oxygen Facials by Intraceuticals - Rejuvenate Anti-Ageing Oxygen (60 min)', 'This skin quenching treatment provides the ultimate in intense hydration. Perfect for all skin types.', 1250000, 'IDR', 0), ('Balinese Boreh', 'Balinese Boreh Body Wrap (90 min)', 'Experience an authentic, century old Balinese Boreh energising treatment that is still used today as a health remedy.', 440000, 'IDR', 0), ('Body Wrap', 'Seaweed Body Wrap (135 min)', 'This oxygenated body exfoliation enhances the penetration of seaweed minerals.', 650000, 'IDR', 0), ('Cream Bath', 'Hair Cream Bath by Loreal (60 min)', 'Enjoy one of these traditional and lavish Indonesian hair treatments.', 250000, 'IDR', 0), ('Waxing', 'Eyebrow Waxing (15 min)', null, 160000, 'IDR', 0), ('Waxing', 'Upper Lip Waxing (5 min)', null, 135000, 'IDR', 1), ('Waxing', 'Full Face Waxing (30 min)', null, 475000, 'IDR', 2), ('Lashes', 'Russian Volume Full Set Eyelash Extensions (120 min)', null, 625000, 'IDR', 0), ('Lashes', 'Natural Full Set Eyelash Extensions (120 min)', null, 595000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

