insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Traditional Massage', 'Bamboo Massage (90 min)', 'Bamboo massage is a technique that offers deep tissue massage with a new touch using bamboo sticks of various lengths and diameters. They can reach inside muscle tissue, improving blood circulation, removing toxins from the body, and renewing blood cell tissue.', 265000, 'IDR', 0), ('Traditional Massage', 'Tension Relieve Massage (30 min)', 'Is a back massage that stimulates circulation and increases blood flow to the area, can help decrease pain in the lower back and reduce muscle tension and stiffness.', 110000, 'IDR', 1), ('Traditional Massage', 'Aloe Vera Massage (75 min)', 'Aloe vera massage is a type of massage that uses aloe vera gel to treat sunburn, soothe skin, promote healing, hydrate, and rejuvenate.', 295000, 'IDR', 2), ('Traditional Massage', 'Four-Hand Massage (90 min)', 'Synchronized four-hand massage performed by two therapists using aromatherapy oil to relieve muscle tension.', 370000, 'IDR', 3), ('Shirodhara', 'Shirodhara Massage (120 min)', 'Shirodhara is a relaxation technique that nourishes the mind, body, and soul. This treatment involves a gentle and continuous stream of warm oil poured onto the forehead, followed by a hair wash to nourish the hair. It provides deep relaxation.', 335000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue Massage (90 min)', 'Deep tissue massage emphasizes the deepest layer of the skin. It reaches deep muscle tissue, which is good for blood pressure, tension release, and stress relief. The pressure used is slower and stronger than that of a regular massage.', 215000, 'IDR', 0), ('Lymphatic Massage', 'Lymphatic Massage (75 min)', 'Lymphatic massage is a gentle massage using warm oil with lemongrass essence. It is good for lymphatic drainage and the movement of lymph fluid throughout the body.', 300000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (60 min)', 'Work on the soles of the feet using thumb pressure and pressure points, which are connected to other parts of the body, to rebalance the energy.', 100000, 'IDR', 0), ('Pregnancy Massage', 'Pregnancy Massage (60 min)', 'As the name suggests, prenatal massage is done on mothers during pregnancy. This massage helps increase blood circulation, relieve soreness in the body muscles, and make you more relaxed.', 200000, 'IDR', 0), ('Hot Stone', 'Hot Stone Massage (90 min)', 'Hot stone massage is a warm treatment that uses heated stones with long, flowing movements to increase body circulation, reduce water retention, and eliminate toxins.', 225000, 'IDR', 0), ('Shiatsu', 'Shiatsu Massage (60 min)', 'Shiatsu Massage is a form of massage that uses the hand, thumb, and bodywork technique that involves applying pressure to specific points on the body.', 245000, 'IDR', 0), ('Swedish', 'Swedish Massage (90 min)', 'Swedish Massage combines relaxing movements with long strokes using palm pressure and warm oil to improve circulation and increase lymphatic flow.', 180000, 'IDR', 0), ('Ayurvedic Treatment', 'Ayurvedic (150 min)', 'Ayurveda is an ancient healing treatment that uses natural oils and holistic approaches to keeping your mind, body, and spirit healthy. Start with a body scrub, body massage, and a facial. Turn to hair treatment to keep hair moisturised and reduce headaches.', 600000, 'IDR', 0), ('Other', 'Perfect Pampering (150 min)', 'Allow your body, mind, and soul to unite. Perfect balance pampering: start with your choice of exfoliating body scrub to remove dead skin cells, followed by a body massage to relax your body and release tension, then continue with a facial treatment to cleanse, exfoliate, and leave your skin clean, balanced, and hydrated.', 550000, 'IDR', 0), ('Other', 'Pure Balance (150 min)', 'Start with stimulation of blood circulation with dry massage, followed by oil massage to release stiff muscles and relax your mind. Rejuvenate your skin with our galvanic facial during the mask. Your therapist will do reiki energy to balance your mind and energy. This is a deeply meditative experience.', 600000, 'IDR', 1), ('Other', 'Ayur Veda (150 min)', 'Your journey will start with purifying exfoliation, followed by a body mask and a flower bath. Continue with body massage using a blend of aromatherapy oils and herbal techniques to release your tension. At the end, your therapist will perform a mini facial to keep your skin moisturised.', 630000, 'IDR', 2), ('Other', 'Beauty Bliss (180 min)', 'A specially designed treatment to re-align the body’s natural elements using Ayurvedic healing. Let stress and tension melt away with a massage using hot stones and aromatherapy oil, then continue with a refreshing facial to condition and moisturise the skin. Finally, enjoy a foot treatment, manicure, or pedicure.', 660000, 'IDR', 3), ('Other', 'Time For Two (120 min)', 'The most romantic spa treatment to try with your partner. Enjoy your time together in the same room. Start with a relaxing body massage to relieve muscle tension, followed by body mask application to smooth and soften the skin. During the massage, your therapist will also give a refreshing facial to rejuvenate your skin, finishing with an aromatic flower bath.', 1170000, 'IDR', 4)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

