select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Balinese Massage', 'Traditional balinese balance (60 min)', 'Tradition runs deep with these Balinese techniques of kneading, long strokes, and acupressure stimulation. Release muscle tension, improve blood circulation and dissolve stress to re-balance and restore our heart to a state of love and gratitude.', 240000, 'IDR', 0), ('Deep Tissue', 'Deep tissue release (60 min)', 'Based on meridians and acupressure points this deeper therapeutic massage loosens muscle tissues, supports blood and oxygen circulation and releases stress, blockage and toxins. Beneficial for chronic pain, injuries or stubborn knots. You will be kneaded, pressed, stretched, elbowed and stroked into bliss.', 260000, 'IDR', 0), ('Hot Stone', 'Hot stone soothe (90 min)', 'A gentle massage to remind us to slow down and remember we have a body. Warm volcanic stones are placed to warm and relax muscles, then long, slow strokes melt away stress and tension. Perfect to induce sleep, reduce anxiety, for arthritis / aching joints or those who prefer a more gentle, nurturing massage.', 380000, 'IDR', 0), ('Reiki', 'Reiki infused surrender (90 min)', 'Beginning with Reiki to receive healing energy throughout your treatment. Reiki brings your therapist into their highest state and opens their heart to transmit good intentions and positive energy throughout your massage. Techniques used include Balinese, Swedish, deep tissue, lomi-lomi, shiatsu, and reiki. Ending with a head and face massage you are brought back to planet Earth and grounded with ', 400000, 'IDR', 0), ('Reiki', 'Reiki chakra reset (30 min)', 'Chakras are the body’s energy centres that spin and distribute our prana / chi / essential life force. These centres get clogged up over time when we experience stress and negative emotions. We clear each of your 7 individual chakras, releasing blockage, then balance your key chakra centres in relation to their corresponding chakra. We also use coloured crystals over your chakras to amplify your h', 140000, 'IDR', 1), ('Shiatsu', 'Shiatsu unfurl (60 min)', 'A strong massage based on Japanese healing systems release muscle and meridian blockages which cause pain physically, mentally and emotionally. Your therapist works deeply, without oil. Techniques used include acupressure with thumbs, palms, elbows, and the occasional foot! This style of massage can be fully clothed if you prefer.', 280000, 'IDR', 0), ('Foot Massage', 'Foot massage earthing (30 min)', 'Acupressure points on your feet correspond with body systems and can release blockages when stimulated. Sit back and relax whilst your therapist washes your feet then gives a soothing lower leg massage infused with foot reflexology to ground you and connect with mother earth.', 140000, 'IDR', 0), ('Facial', 'Facial – Ibu earth (60 min)', 'Our most popular facial is freshly prepared daily from organic ingredients including natural fruits, oils, seeds, plants, honey and clay to cleanse, exfoliate, tone and moisturise your skin. Included is a gentle neck, arm and leg massage.', 240000, 'IDR', 0), ('Facial', 'Facial – Sanctum (60 min)', 'Sanctum is a range of certified organic, cruelty free, natural facial products from Australia. A perfect fresh lift for your skin. We begin with a cleanse and gentle exfoliant to thoroughly prepare your skin for active ingredients. Whilst your hydrating masque infuses enjoy a neck, arm and leg massage before eye balm and moisturiser are applied.', 300000, 'IDR', 1), ('Manicure', 'Manicure (60 min)', 'After a warm hand soak we cleanse, trim, shape, buff and beautify your nails and cuticles. Polish of your choice is applied and enjoy a hand and arm massage.', 220000, 'IDR', 0), ('Pedicure', 'Pedicure (60 min)', 'Pamper your feet so your toes and heels look and feel healthy. We begin with a foot scrub, then get down to the business of gently removing dry skin and callouses before trimming and shaping your nails. Your treatment includes a relaxing foot massage then we apply colour of your choice.', 220000, 'IDR', 0), ('Cream Bath', 'Infusion – Hair Cream Bath (60 min)', 'We shampoo your hair with our seaweed infused shampoo, then apply a deeply nourishing hair mask treatment that contains candlenut, jojoba and essential oils. Enjoy a deep scalp massage before we wrap your hair in a hot towel and massage your neck, shoulders and arms. Enjoy your soft, shiny, healthy hair.', 240000, 'IDR', 0), ('Other', 'Green Tara compassion (150 min)', 'Your choice of 60 minute massage - Traditional Balinese balance or Foot Massage Earthing plus Reiki chakra reset followed by your choice of Facial – Ibu Earth or Infusion – Hair Cream Bath.', 600000, 'IDR', 0), ('Other', 'Kwan Yin unconditional love (270 min)', 'Your choice of 90 minute massage - Hot stone soothe or Traditional Balinese balance or Deep tissue release plus any body scrub, mask and bath combo followed by your choice of Facial–Ibu Earth or Infusion – Hair Cream Bath plus manicure or pedicure.', 1050000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'balibotanica.com' and status = 'active' and publication_status = 'published' and category in ('spa', 'beauty', 'yoga', 'fitness') order by case category when 'spa' then 0 when 'beauty' then 1 else 2 end, slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Bali Botanica Ubud treatment prices',
         coalesce((select max(mx.version) from menus mx where mx.venue_slug = t.slug), 0) + 1,
         'draft', 'partial', 'https://balibotanica.com/traditional-treatments', 'Official Bali Botanica Ubud price list',
         '2026-08-25T05:28:30+00:00'::timestamptz, null, '2026-11-23T05:28:30+00:00'::timestamptz, '758dc937a6563a9a3174974ef61743eba8d3a91c9d91f2fb0a6f916143175136', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug
                    and x.status in ('source_snapshot', 'published'))
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Traditional Massage', 0), ('Balinese Massage', 1), ('Other', 2), ('Javanese Lulur', 3), ('Ice Bath', 4), ('Body Treatment', 5), ('Foot Massage', 6), ('Facial', 7), ('Cream Bath', 8), ('Ayurvedic Treatment', 9), ('Spa Package', 10)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Traditional Massage', 'Relaxing Massage (75 min)', 'Warm herbal oil is poured onto your body, followed by a soothing Ayurvedic-inspired massage to calm the nervous system and relieve deep stress, leaving you balanced, relaxed, and fully restored.', 375000, 'IDR', 0), ('Balinese Massage', 'Balinese Massage (60 min)', 'Experience Balinese massage techniques—pressure points, palm pressure, sliding, and kneading for deep relaxation. Release muscle tension, ease pain, and enjoy profound therapeutic benefits.', 325000, 'IDR', 0), ('Other', 'Exfoliation and Bath (45 min)', 'Choose your scrub—lulur, milk, coffee, or green tea—to revitalize your skin. Finish your treatment by relaxing in a beautiful floral bath for a perfect, refreshing feeling.', 350000, 'IDR', 0), ('Other', 'Mandi Susu – Milk Bath (120 min)', 'Experience a timeless beauty ritual inspired by Cleopatra, with a 75-minute relaxing massage, a gentle milk scrub, and a fragrant floral bath for soft, smooth, and glowing skin.', 550000, 'IDR', 1), ('Other', 'Mandi Kopi – Coffee Bath (120 min)', 'Enjoy an invigorating treatment with a 75-minute relaxing massage, a coffee scrub to smooth and tone the skin, and a fragrant floral bath for a refreshed, renewed feeling.', 550000, 'IDR', 2), ('Other', 'Mandi Teh Hijau – Green Tea Bath (120 min)', 'A detoxifying treatment featuring a 75-minute relaxing massage, followed by a green tea scrub to rejuvenate the skin. Finish with a beautiful floral bath for a radiant and refreshed glow.', 550000, 'IDR', 3), ('Other', 'Floral Bath Only (30 min)', 'Immerse yourself in a fresh flower petal bath designed to rejuvenate the senses. Enjoy a quiet moment of relaxation for the body and mind.', 250000, 'IDR', 4), ('Other', 'Hibiscus Hair Shampoo (30 min)', 'This centuries-old Indonesian ritual cleanses and nourishes your scalp with hibiscus extract to stimulate growth, prevent graying, and reveal lustrous hair.', 150000, 'IDR', 5), ('Other', 'A Day at Botanica (375 min)', 'A day of divine pampering starts with a Chakra Dhara, pouring soothing herbal oil over your energy centers, followed by an Ayurvedic massage and full-body scrub. Luxuriate in a flower bath, then enjoy an Ayurvedic facial and nourishing hair treatment. Emerge from this experience feeling revitalized from head to toe.', 2025000, 'IDR', 6), ('Other', 'A Taste of Ayurveda (195 min)', 'Unwind with a 2.5-hour Ayurvedic Chakra Dhara, warm herbal oil is dripped onto the Chakra points, followed by a deep healing massage to promote blood circulation, increase flexibility, and relieve pain. Your treatment concludes with a body exfoliation and soak in a floral bath.', 1195000, 'IDR', 7), ('Other', 'Pure Relaxing (150 min)', 'An indulgent 2,5 hours escape, dedicated to deep relaxation and nurturing. Begin with a tension-melting Balinese massage, experience tranquil bliss with an Ayurvedic Shirodara, followed by a rejuvenating full-body exfoliation. Then unwind in a luxurious flower bath as you embrace complete tranquility.', 1150000, 'IDR', 8), ('Other', 'Romantic Escape for Two (180 min)', 'Indulge in 3 hours of pampering with your loved one, starting with a blissful relaxing massage, followed by luxurious full-body exfoliation, a fragrant flower bath, and a rejuvenating facial—all in the intimate setting of our romantic couples’ room overlooking the jungle.', 2050000, 'IDR', 9), ('Javanese Lulur', 'Mandi Lulur – Floral Bath (120 min)', 'Experience a 17th-century Javanese royal treatment with a 75-minute relaxing massage, a traditional full-body spice scrub, and a fragrant floral bath overlooking the jungle.', 550000, 'IDR', 0), ('Ice Bath', 'Mandi Rempah – Spice Bath (120 min)', 'Experience a 75-minute relaxing massage, a warming spice scrub to improve circulation, and an aromatic herbal bath to soothe, restore, and renew your body.', 550000, 'IDR', 0), ('Body Treatment', 'Coconut Body Treatment (120 min)', 'A deeply hydrating ritual combining a relaxing massage, a gentle coconut body scrub, and a fresh flower bath—ideal for dry and compromised skin.', 550000, 'IDR', 0), ('Foot Massage', 'Foot Spa (60 min)', 'Treat your feet to a relaxing foot spa with a salt and lime soak, nail care, and a 25-minute massage for your feet and lower legs, leaving them refreshed, smooth, and well-groomed.', 275000, 'IDR', 0), ('Facial', 'Gel Mask Facial (60 min)', 'Our therapists gently cleanse and exfoliate your skin before applying a Bio-Aloe Vera mask that hydrates the skin and locks in moisture. The perfect soothing facial for normal to dry skin types, and those who have caught too much Bali sun.', 350000, 'IDR', 0), ('Facial', 'Thermal Clay Facial (60 min)', 'Specially crafted for oily or sensitive skin types, our Balinese clay facial is nature’s facelift! After the therapists gently cleanse and exfoliate your skin, a thermal clay mask is applied to your face and neck to purify and hydrate your skin, restoring its radiance.', 350000, 'IDR', 1), ('Cream Bath', 'Hair Cream Bath (60 min)', 'Rejuvenate dull hair with an avocado cream scalp massage to stimulate circulation and promote growth, followed by a steam bath to lock in moisture for healthy, shiny hair.', 300000, 'IDR', 0), ('Ayurvedic Treatment', 'Ayurvedic Facial (60 min)', 'Our therapists gently cleanse and exfoliate your skin using a classic blend of antioxidant-rich herbs. A soothing Marma point massage calms you, before steam deeply purifies your pores. This facial revives skin texture, restores elasticity to prevent aging and gives you a radiant glow.', 400000, 'IDR', 0), ('Spa Package', 'Bali Byasa Package (240 min)', 'Drift into 4 blissful hours of pure self-care, indulging in the most beloved Bali spa experiences—a dreamy escape your body and soul truly deserve.', 1250000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

