join (values ('Foot Massage', 'Foot Massage (30 min)', 'Through gentle manipulation and aromatic oil, target pressure points and soothe tired muscles in your feet.', 95000, 'IDR', 0), ('Foot Massage', 'Foot Massage (60 min)', 'Through gentle manipulation and aromatic oil, target pressure points and soothe tired muscles in your feet.', 190000, 'IDR', 1), ('Foot Massage', 'Signature Pedicure Footlogix with Polish & Callus (70 min)', 'Give your skin smoother by foot bath & scrubbing, relaxing massage in feet complete with classic pedicure, nail cutting, nail shaping, cuticle care, nail polish applications, callus shaver.', 260000, 'IDR', 2), ('Foot Massage', 'Signature Pedicure Footlogix with Callus (60 min)', 'Foot bath & scrubbing, relaxing massage in feet, complete with classic pedicure, nail cutting, nail shaping, cuticle care, callus shaver.', 250000, 'IDR', 3), ('Foot Massage', 'Relaxing Foot Massage (60 min)', 'A relaxing Foot Massage in Ubud, Bali designed to relieve tired feet and restore overall body balance. Using traditional pressure point techniques, this treatment helps improve blood circulation, reduce muscle tension, and promote deep relaxation after a long day of exploring Ubud.', 190000, 'IDR', 4), ('Foot Massage', 'Relaxing Foot Massage (30 min)', 'A relaxing Foot Massage in Ubud, Bali designed to relieve tired feet and restore overall body balance. Using traditional pressure point techniques, this treatment helps improve blood circulation, reduce muscle tension, and promote deep relaxation after a long day of exploring Ubud.', 95000, 'IDR', 5), ('Reflexology', 'Foot Reflexology (30 min)', 'An ancient healing art, focused applying pressure to specific points on the feet that correspond to organs and system in the body, promoting wellness and relaxations.', 105000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (60 min)', 'An ancient healing art, focused applying pressure to specific points on the feet that correspond to organs and system in the body, promoting wellness and relaxations.', 210000, 'IDR', 1), ('Reflexology', 'Traditional Foot Reflexology (60 min)', 'Foot Reflexology in Ubud, Bali is an ancient healing art, focused applying pressure to specific points on the feet that correspond to organs and system in the body, promoting wellness and relaxations', 210000, 'IDR', 2), ('Reflexology', 'Traditional Foot Reflexology (30 min)', 'Foot Reflexology in Ubud, Bali is an ancient healing art, focused applying pressure to specific points on the feet that correspond to organs and system in the body, promoting wellness and relaxations', 105000, 'IDR', 3), ('Head Massage', 'Head Massage (30 min)', 'A relaxing treatment focusing on the scalp, neck, and shoulders. Helps relieve stress, tension headaches, and promotes better blood circulation.', 95000, 'IDR', 0), ('Traditional Massage', 'Hand Massage (30 min)', 'Targets pressure points in the hands to relieve tension, improve circulation and reduce stress.', 95000, 'IDR', 0), ('Traditional Massage', 'Herbal Massage (90 min)', 'Deeply relaxing massage using warm herbal compresses filled with traditional Balinese herbs to relieve muscle tension, detoxify the body, enhancing relaxation & better sleep.', 450000, 'IDR', 1), ('Traditional Massage', 'Herbal Massage (120 min)', 'Deeply relaxing massage using warm herbal compresses filled with traditional Balinese herbs to relieve muscle tension, detoxify the body, enhancing relaxation & better sleep.', 600000, 'IDR', 2), ('Neck & Shoulder', 'Back, Neck & Shoulder Massage (30 min)', 'Using a fusion of soothing techniques and therapeutic pressure, design to alleviate muscle stiffness, improve circulation,and promote relaxation.', 150000, 'IDR', 0), ('Neck & Shoulder', 'Back, Neck & Shoulder Massage (60 min)', 'Using a fusion of soothing techniques and therapeutic pressure, design to alleviate muscle stiffness, improve circulation,and promote relaxation.', 300000, 'IDR', 1), ('Balinese Massage', 'Balinese Massage (60 min)', 'Traditional Balinese massage use a combination of gentle stretches, firm pressure, and long, flowing strokes to stimulate blood circulation, deeply relaxing and soft.', 230000, 'IDR', 0), ('Balinese Massage', 'Balinese Massage (90 min)', 'Traditional Balinese massage use a combination of gentle stretches, firm pressure, and long, flowing strokes to stimulate blood circulation, deeply relaxing and soft.', 345000, 'IDR', 1), ('Balinese Massage', 'Balinese Massage (120 min)', 'Traditional Balinese massage use a combination of gentle stretches, firm pressure, and long, flowing strokes to stimulate blood circulation, deeply relaxing and soft.', 460000, 'IDR', 2), ('Couple Massage', 'Balinese Couple Massage (60 min)', 'A wonderful way for partners to relax together, bond,and experience the benefits of massage therapy in a shared and intimate setting.', 460000, 'IDR', 0), ('Couple Massage', 'Balinese Couple Massage (90 min)', 'A wonderful way for partners to relax together, bond,and experience the benefits of massage therapy in a shared and intimate setting.', 690000, 'IDR', 1), ('Couple Massage', 'Balinese Couple Massage (120 min)', 'A wonderful way for partners to relax together, bond,and experience the benefits of massage therapy in a shared and intimate setting.', 920000, 'IDR', 2), ('Other', 'Jhagat Signature (60 min)', 'Crafted to provide unparalleled relaxation and rejuvenation with Balinese spices oil.', 250000, 'IDR', 0), ('Other', 'Jhagat Signature (90 min)', 'Crafted to provide unparalleled relaxation and rejuvenation with Balinese spices oil.', 375000, 'IDR', 1), ('Other', 'Jhagat Signature (120 min)', 'Crafted to provide unparalleled relaxation and rejuvenation with Balinese spices oil.', 500000, 'IDR', 2), ('Other', 'Vital Nutritions (35 min)', 'Nourish your skin with essential nutrients and vitamins, promoting a radiant complexion and overall skin health. This treatment deeply hydrates and revitalizes, leaving your skin feeling refreshed and rejuvenated.', 230000, 'IDR', 3), ('Other', 'Age Renew (35 min)', 'Target signs of aging and skin elasticity. Involves a combination of exfoliation deep cleansing, and moisturize the skin. Help to improve the appearance of aging skin and promote a more youthful complexion.', 230000, 'IDR', 4), ('Other', 'Deep Cleansing (35 min)', 'Purify and renew your skin with intensive cleansing treatment. Ideal for removing impurities, unclogging pores, and restoring clarity to your complexion.', 230000, 'IDR', 5), ('Other', 'LED Therapy (35 min)', null, 230000, 'IDR', 6), ('Other', 'LED Therapy (50 min)', null, 400000, 'IDR', 7), ('Other', 'Creambath (45 min)', 'Deeply moisturizes and hydrates the hair, repair damaged hair, reducing breakage and split ends.', 190000, 'IDR', 8), ('Other', 'Styling (20 min)', 'The process of arranging and shaping hair by using hair straightener, hair curler, or curler waves to achieved a desired look.', 100000, 'IDR', 9), ('Deep Tissue', 'Deep Tissue (60 min)', 'The strong massage, focuses on reaching the deeper layers of muscles and connective tissue, target knots and areas of tension in the body.', 250000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue (90 min)', 'The strong massage, focuses on reaching the deeper layers of muscles and connective tissue, target knots and areas of tension in the body.', 375000, 'IDR', 1), ('Deep Tissue', 'Deep Tissue (120 min)', 'The strong massage, focuses on reaching the deeper layers of muscles and connective tissue, target knots and areas of tension in the body.', 500000, 'IDR', 2), ('Aromatherapy', 'Aromatherapy (60 min)', 'Use of aromatic essential oils derived from plants to enhance physical and emotional well-being.', 250000, 'IDR', 0), ('Aromatherapy', 'Aromatherapy (90 min)', 'Use of aromatic essential oils derived from plants to enhance physical and emotional well-being.', 375000, 'IDR', 1), ('Aromatherapy', 'Aromatherapy (120 min)', 'Use of aromatic essential oils derived from plants to enhance physical and emotional well-being.', 500000, 'IDR', 2), ('Hot Stone', 'Hot Stone (90 min)', 'The soothing warmth of the stones, combined with the therapeutic benefits of massage, treat a variety of conditions including muscle tension, stress, anxiety and insomnia.', 450000, 'IDR', 0), ('Hot Stone', 'Hot Stone (120 min)', 'The soothing warmth of the stones, combined with the therapeutic benefits of massage, treat a variety of conditions including muscle tension, stress, anxiety and insomnia.', 600000, 'IDR', 1), ('Body Scrub', 'Green Tea Body Scrub (35 min)', 'The gentle exfoliation of green tea helping slough off dead skin and reveal a smoother, brighter complexion. Offers benefit of antioxidants, antibacterial, and acne fighting in your body.', 220000, 'IDR', 0), ('Body Scrub', 'Java Jolt Coffee Scrub (35 min)', 'Natural exfoliant helping to remove dead skin, reveal smoother, and softer skin. Caffeine in coffee reduce the appearance of cellulite, reduce redness and neutralize free radical.', 220000, 'IDR', 1), ('Body Scrub', 'Add On Body Scrub (15 min)', null, 130000, 'IDR', 2), ('Balinese Boreh', 'Balinese Boreh (35 min)', 'A traditional Balinese herbal remedy which act as natural exfoliants, detoxification and moisturization.', 220000, 'IDR', 0), ('Body Mask', 'Add On Body Mask (15 min)', null, 130000, 'IDR', 0), ('Hair Styling', 'Hair Wash (20 min)', 'Excess oil and impurities from the hair and scalp. Refresh and revitalize the hair, leave it feeling clean and balanced.', 100000, 'IDR', 0), ('Manicure', 'Simple Manicure (20 min)', 'Simple care with classic dry manicure, nail cutting, nail shaping, cuticle care without nail polish.', 100000, 'IDR', 0), ('Manicure', 'Simple Manicure with Polish (40 min)', 'Simple care with classic dry manicure, nail cutting, nail shaping, cuticle care with nail polish.', 150000, 'IDR', 1), ('Manicure', 'Signature Manicure with Polish (45 min)', 'Give your skin smoother by hand bath & scrubbing, relaxing massage in hand complete with classic manicure, nail cutting, nail shaping, cuticle care and nail polish applications.', 170000, 'IDR', 2), ('Manicure', 'Manicure Gel (60 min)', 'Prioritized nail care protection while providing a glossy, longlasting finish nail gel colour, with cuticle care.', 150000, 'IDR', 3), ('Manicure', 'Manicure BIAB (120 min)', 'Builder gel manicure designed to strengthen, smooth, and protect natural nails.', 200000, 'IDR', 4), ('Manicure', 'Kids Manicure Polish (25 min)', 'Gentle nail care specially for kids, includes nail shaping and application of nail polish.', 100000, 'IDR', 5), ('Pedicure', 'Simple Pedicure (20 min)', 'Simple care with classic pedicure, nail cutting, nail shaping, cuticle care without nail polish.', 120000, 'IDR', 0), ('Pedicure', 'Simple Pedicure with Polish (40 min)', 'Simple care with classic dry pedicure, nail cutting, nail shaping, cuticle care with nail polish.', 150000, 'IDR', 1), ('Pedicure', 'Pedicure Nail Gel (60 min)', 'Prioritized nail care protection while providing a glossy, longlasting finish nail gel colour, with cuticle care.', 160000, 'IDR', 2), ('Pedicure', 'Kids Pedicure Polish (25 min)', 'Gentle nail care specially for kids, includes nail shaping and application of nail polish.', 100000, 'IDR', 3)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

