select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Traditional Massage', 'Bamboo Drainage Massage (90 min)', 'A combination of deep tissue therapy, manual drainage massage, and long flowing massage strokes and rolling with bamboo sticks.', 850000, 'IDR', 0), ('Traditional Massage', 'Mahamaya Herbal Massage (90 min)', 'Inspired by the herbal used by Balinese People to relax muscles through warm herbal compress.', 750000, 'IDR', 1), ('Traditional Massage', 'River Stone Massage (90 min)', 'Utilizing warm stone to melt deep muscle tension and release burdens of everyday living.', 750000, 'IDR', 2), ('Traditional Massage', 'Focused Massage (30 min)', 'Express treatment perfect for anyone seeking relaxation in a busy schedule.', 390000, 'IDR', 3), ('Traditional Massage', 'Bamboo Drainage Massage (90 min)', 'In the Eastern world, bamboo is a symbol of longevity because of its strength, flexibility, & resilience. Bamboo massage is known for its restorative properties to stimulate the flow of blood and lymph and relieve muscle tension. A combination of deep tissue therapy, manual drainage massage, and long flowing massage strokes and rolling with bamboo sticks combines in our signature massage to soothe', 790000, 'IDR', 4), ('Traditional Massage', 'Mahamaya Herbal Massage (90 min)', 'Inspired by the herbal that has long been used by Balinese People, the warm herbal compress invites your muscle to relax. The warm mixture of the herbs in the relaxing massage flow helps to reduce aches and gives an ultimate boost to your well-being.', 690000, 'IDR', 5), ('Traditional Massage', 'River Stone Massage (90 min)', 'Utilizing the warm stone to melt deep muscle tension, River stone massage will release the burdens of everyday living and nurture your body and mind. The therapist carefully places the warm stone on different chakra points in a rhythmic relaxing massage.', 690000, 'IDR', 6), ('Traditional Massage', 'Focused Massage (30 min)', 'Express treatment that perfect for anyone who seeks relaxation in a busy schedule. Choices: neck & shoulder / backfoot massage', 350000, 'IDR', 7), ('Lymphatic Massage', 'Lymphatic Drainage Massage (60 min)', 'Designed to encourage the movement of lymph fluid to enhance elimination of toxins and water retention.', 650000, 'IDR', 0), ('Lymphatic Massage', 'Lymphatic Drainage Massage (90 min)', null, 790000, 'IDR', 1), ('Lymphatic Massage', 'Lymphatic Drainage Massage (90 min)', 'This massage technique is designed to encourage the movement of lymph fluid. By stimulating circulation through a rhythmic motion in the direction of the lymphatic flow, it will enhance the elimination of toxins, alleviate water retention, and relieve bloating.', 750000, 'IDR', 2), ('Lymphatic Massage', 'Lymphatic Drainage Massage (60 min)', null, 590000, 'IDR', 3), ('Deep Tissue', 'Deep Tissue Massage (90 min)', 'Targets deeper tissues under your skin using warm oil and a warm towel ritual.', 690000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue Massage (60 min)', null, 550000, 'IDR', 1), ('Deep Tissue', 'Deep Tissue Massage (90 min)', 'Our signature deep tissue massage is designed to target deeper tissues under your skin using warm oil and a warm towel ritual. Performed with a slow and deliberate technique passed down through generations, it helps relieve the stiffness and encourages a sense of deep relaxation.', 650000, 'IDR', 2), ('Deep Tissue', 'Deep Tissue Massage (60 min)', null, 490000, 'IDR', 3), ('Balinese Massage', 'Relaxing Balinese massage (90 min)', 'Performed using long strokes, palm press, thumb press, and gentle stretching.', 650000, 'IDR', 0), ('Balinese Massage', 'Relaxing Balinese massage (60 min)', null, 490000, 'IDR', 1), ('Balinese Massage', 'Relaxing Balinese massage (90 min)', 'Feel the tension dissolve with the ancient wisdom of Balinese treatment that is performed using long strokes, palm press, thumb press, and gentle stretching. A rhythmic experience evokes a sense of relaxation and stimulates the blood flow.', 590000, 'IDR', 2), ('Balinese Massage', 'Relaxing Balinese massage (60 min)', null, 450000, 'IDR', 3), ('Reflexology', 'Foot Reflexology (60 min)', 'Intensely healing treatment to target specific points on the feet.', 450000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (60 min)', 'An intensely healing treatment to target specific points on the feet to boost the inner energy through the body’s meridian', 390000, 'IDR', 1), ('Other', 'Advanced Anti-Cellulite Care by Tegoder - Arm / Abs / Hip & Thigh (45 min)', 'Revolutionary therapy combining Eastern & Western medicine to improve circulation and reduce cellulite.', 590000, 'IDR', 0), ('Other', 'Advanced Anti-Cellulite Care by Tegoder - Full Leg (60 min)', null, 790000, 'IDR', 1), ('Other', 'Advanced Anti-Cellulite Care by Tegoder - Full Body (Arm, Abdomen, Hip, Full Leg) (120 min)', null, 1590000, 'IDR', 2), ('Other', 'Authentic Hair Crème Bath (75 min)', 'Indonesian beauty ritual using strawberry and yogurt extracts to nourish hair.', 550000, 'IDR', 3), ('Other', 'Cleopatra''s Rose Milk bath (30 min)', 'A milk bath scented with essential oil to boost hydration and soothe the mind.', 390000, 'IDR', 4), ('Other', 'Holistic Cellulite Therapy by Tegoder (150 min)', 'Full-body holistic therapy to combat cellulite and promote skin firmness.', 1990000, 'IDR', 5), ('Other', 'Self-Love Journey (180 min)', 'Invigorating ritual to balance body and soul with multiple treatments.', 1490000, 'IDR', 6), ('Other', 'Signature Nyuh (Coconut) Sensation (180 min)', 'Holistic package with coconut treatments to rejuvenate the body.', 1290000, 'IDR', 7), ('Other', 'Blissful Mahamaya Journey (150 min)', 'Signature experience capturing the essence of Balinese herbs for calmness.', 1250000, 'IDR', 8), ('Other', 'Rama & Shinta Refresher (150 min)', 'Couple package including river stone massage and herbal bath.', 2290000, 'IDR', 9), ('Other', 'Honeymoon Enjoyment (120 min)', 'Relaxing treatment for couples including Balinese massage and milk polish.', 1990000, 'IDR', 10), ('Other', 'Romantic Bubble Bliss (90 min)', 'Romantic treatment includes Balinese massage and aromatherapy bubble bath.', 1090000, 'IDR', 11), ('Other', 'Red Carpet Hydra Glow (90 min)', 'Non-invasive facial treatment for brightening and tightening skin.', 1290000, 'IDR', 12), ('Other', 'Bootylicious (75 min)', 'Treatment designed to cleanse and rejuvenate the booty area.', 1050000, 'IDR', 13), ('Other', 'Backne Care (75 min)', 'Cleansing and soothing treatment for back skin.', 1290000, 'IDR', 14), ('Other', 'Holistic Cellulite Therapy by Tegoder (150 min)', 'Indulge in a full-body holistic skin-firming therapy to reveal softer skin & combat the cellulite. A blend of scientifically proven ingredients with anti cellulite massage technique improves metabolic circulation, and diminishes cellulite, leaving the skin’s texture visibly plumper & smoother. The treatment is followed by a toning wrap in an infrared thermal blanket to eliminate the toxin & excess', 1990000, 'IDR', 15), ('Other', 'Advanced Anti-Cellulite Care by Tegoder (Arm / Abs / Hip & Thigh) (45 min)', 'This revolutionary therapy combines the goodness of East medicine to improve circulation with West medicine to tighten the loose skin. The treatment starts with anti cellulite massage using a scientifically proven solution that contains Lipoglaucin, L-carnitine, bitter orange, & enzymatic complex to induce lipolysis and reduce the appearance of the cellulite. It is followed by the application of a', 590000, 'IDR', 16), ('Other', 'Advanced Anti-Cellulite Care by Tegoder (Full Leg) (60 min)', null, 790000, 'IDR', 17), ('Other', 'Advanced Anti-Cellulite Care by Tegoder (Full Body) (120 min)', null, 1590000, 'IDR', 18), ('Other', 'Authentic Hair Crème Bath (75 min)', 'The secret of the Indonesian beauty ritual that uses extracts blends of strawberry and yogurt containing Vitamin C and amino acids act to nourish and revive dry, damaged hair and leave hair smelling fresh and divine. A gentle head massage promotes scalp circulation and gloss, while the neck and shoulder massage boost your overall well-being.', 550000, 'IDR', 19), ('Other', 'Cleopatra''s Rose Milk bath (30 min)', 'Inspired by Cleopatra''s ritual, boost your skin hydration even more in a milk bath scented with pure essential oil to calm your mind. A dash of fresh rose petals will brighten your mood for the remainder of the day.', 290000, 'IDR', 20), ('Other', 'Island Frangipani Milk Bath (30 min)', 'Luxuriate in a warm bath of pure coconut milk and fresh frangipani petals to soften the skin and uplift the sense of well being.', 290000, 'IDR', 21), ('Other', 'Self-Love Journey (180 min)', 'Indulge your self an invigorating ritual to create profound balance and harmony in your body and soul. Beginning with a relaxing Balinese Massage, step into coconut body scrub to exfoliate the dead cell, and finished with milk body polish to promote skin hydration. Lastly, spoil yourself with our tropical Balinese flower bath while enjoying a light and healthy spa cuisine as your body & mind deser', 1390000, 'IDR', 22), ('Other', 'Signature Nyuh (Coconut) Sensation (180 min)', 'Connecting you with the vital element of Balinese wellness, this holistic package will begin with a relaxing Balinese massage, followed by a coconut body scrub and coconut body wrap. Last, complete the journey with a skin nourishing session with an island frangipani milk bath made from pure coconut milk to refresh your body. From head to toe, you will feel rejuvenated and revitalized.', 1190000, 'IDR', 23), ('Other', 'Blissful Mahamaya Journey (150 min)', 'Capturing the goodness of nature, this signature experience delivers the benefit of Balinese herbal to calm your body and mind. Beginning with the herbal massage, discover the warmth and healing sensation of Balinese boreh, and followed by the energized herbal bath to promote the inner energy from within.', 1190000, 'IDR', 24), ('Other', 'Rama & Shinta Refresher (150 min)', 'This Balinese couple package is curated to help you recover from the mental strains of modern living. Beginning with a river stone massage, step into Balinese boreh spice wrap to warm up your body. Finish the ritual with enegizing and our signature herbal bath consisting of traditional blends of herbs that will allow you to feel physically and emotionally grounded.', 2150000, 'IDR', 25), ('Other', 'Honeymoon Enjoyment (120 min)', 'Dedicated to relieving the tension while sharing intimacy with your partner, this honeymoon package includes Balinese massages and milk body polish to give a boost to your skin. To end the treatment, immerse yourself and your love in a tropical Balinese flower bath ritual.', 1950000, 'IDR', 26), ('Other', 'Romantic Bubble Bliss (90 min)', 'This dreamy spa package is designed exclusively for busy couples wanting to gift themselves with pampering time together. This romantic treatment consists of a Balinese massage for couples and an aromatherapy bubble bath with rose petals to enhance the romantic sensation.', 1090000, 'IDR', 27), ('Body Scrub', 'Refreshing Citrus Body Scrub (30 min)', 'Softening exfoliation using organic salt, lemongrass, and mandarin orange.', 350000, 'IDR', 0), ('Body Scrub', 'Exotic Flower Body Scrub (30 min)', 'Infused with traditional blends of Balinese flowers to gently remove dead skin.', 350000, 'IDR', 1), ('Body Scrub', 'Traditional Coconut Body Scrub (30 min)', 'Natural way to buff away dead skin cells while soothing skin with coconut.', 350000, 'IDR', 2), ('Body Scrub', 'Refreshing Citrus Body Scrub (30 min)', 'Reveal nourished and supple skin with this softening exfoliation using a tropical cocktail of organic salt, lemongrass, and mandarin orange. Exfoliate your skin and let it shine.', 290000, 'IDR', 3), ('Body Scrub', 'Exotic Flower Body Scrub (30 min)', 'Infused with traditional blends of Balinese flowers, the salt’s granule gently removes the dead skin while moisturizing it, leaving you with smooth skin.', 290000, 'IDR', 4), ('Body Scrub', 'Traditional Coconut Body Scrub (30 min)', 'Experience a recipe from our ancestors for smooth, glowing skin. A traditional and natural way to buff away dead skin cells gently while the antioxidant power of coconut leaves skin soothed and toned.', 290000, 'IDR', 5), ('Balinese Boreh', 'Boreh Herbal Ritual (30 min)', 'Blend of ginger, cinnamon, cloves, and sandalwood applied gently to warm the body.', 290000, 'IDR', 0), ('Balinese Boreh', 'Boreh Spice Wrap (30 min)', 'Boreh has been used for centuries by Balinese farmers to warm the body and relieve fatigue. A blend of ginger, cinnamon, cloves, and sandalwood is applied to the skin and gently massaged into your body. This is a perfect treatment if you experience jet lag or need a boost. Enjoy a heavenly scalp massage while your body is polished in the body wrap.', 290000, 'IDR', 1), ('Body Mask', 'Purifying Coconut Body Mask (30 min)', 'Coconut mask to moisturize and destress skin, includes a heavenly scalp massage.', 290000, 'IDR', 0), ('Hydrating Facial', 'Hydrating Milk Body Polish (30 min)', 'Milk body polish to soften and rejuvenate skin with mild exfoliating properties.', 290000, 'IDR', 0), ('Hydrating Facial', 'Hydrating Milk Body Polish (30 min)', 'Milk body polish softens and rejuvenates the skin with mild exfoliating properties to eliminate dead skin cells. Enjoy a heavenly scalp massage while your body is polished in the body wrap.', 290000, 'IDR', 1), ('Shirodhara', 'Mahamaya Shirodara Treatment (90 min)', 'Ayurvedic treatment to relieve anxiety and restore calmness with warm herbal oil.', 850000, 'IDR', 0), ('Shirodhara', 'Mahamaya Shirodara Treatment (90 min)', 'The key Ayurvedic treatment is to relieve anxiety and restores calmness from within. This ancient treatment has been practiced for centuries and is believed to help treat insomnia & burnout. Our signature Shirodhara begins with a welcoming short neck & shoulder massage. Once you are relaxed, the therapists will pour warm herbal oil over the 6th Ajna chakra point in the center of your forehead, fam', 750000, 'IDR', 1), ('Hair Treatment', 'Intensive Hair SPA (75 min)', 'Revitalizing hair treatment utilizing aloe vera to strengthen roots.', 550000, 'IDR', 0), ('Hair Treatment', 'Intensive Hair SPA (75 min)', 'An intensive fragrant treatment to revitalize the hair utilizing the legendary aloe vera extract, a well-known ingredient that helps prevent hair loss by strengthening the roots. Spoil yourself even more with the scalp massage that is designed to enhance nutrient’s penetration and the mahamaya classic massage that target muscle soreness in the neck and shoulder', 550000, 'IDR', 1), ('Hair Styling', 'Hair Wash with Vitamin (30 min)', 'Express treatment to cleanse and nourish scalp and hair.', 350000, 'IDR', 0), ('Hair Styling', 'Hair Wash with Vitamin (30 min)', 'Say no more to the bad hair day. Express treatment to cleanse your scalp and nourish your hair.', 250000, 'IDR', 1), ('Flower Bath', 'Tropical Balinese Flower Bath (30 min)', 'A handcrafted flower bath with ylang ylang essential oil for relaxation.', 550000, 'IDR', 0), ('Flower Bath', 'Tropical Balinese Flower Bath (30 min)', 'Experience being the Balinese queen with a handcrafted flower bath and let the flowers spoil your body and mind. The bath is also infused with ylang ylang essential oil to enhance your soul journey. No wonder, It has become everybody''s favorite to create a memorable moment in Ubud.', 550000, 'IDR', 1), ('Ice Bath', 'Balinese Warm Spice Bath (30 min)', 'Soak infused with Tenglang tea and Balinese flowers that calms the mind.', 490000, 'IDR', 0), ('Herbal Bath', 'Energizing Herbal Bath (30 min)', 'Herbal bath with pandanus leaves, ginger, and lime for relaxation.', 490000, 'IDR', 0), ('Herbal Bath', 'Energizing Herbal Bath (30 min)', 'Leisurely soak away your stress in the purity of nature with the aromatic blend of pandanus leaves, ginger, lime, and betel leaves. This Balinese herbal combination, along with the pure essential oil, encourages relaxation leaving the body refreshed and energized.', 450000, 'IDR', 1), ('Recovery', 'Stress Recovery (120 min)', 'Classic ritual featuring stone massage and coconut body mask to relieve tension.', 1090000, 'IDR', 0), ('Recovery', 'Stress Recovery (120 min)', 'Breathe into a classic ritual to relieve body tension and let go things that no longer serve you. This treatment features deep tissue massage to relieve the stubborn muscle tension, coconut body wrap to boost your skin’s antioxidant, and complete with an aromatherapy bubble bath that will help to de-stress.', 950000, 'IDR', 1), ('Spa Package', 'Cleopatra''s Indulging Ritual (120 min)', 'Royalty treatment that includes Balinese massage and skin exfoliation.', 1090000, 'IDR', 0), ('Spa Package', 'Cleopatra''s Indulging Ritual (120 min)', 'Gift yourself once in a while. Throw back to the ancient time, and feel the royalty of Cleopatra''s ritual to unwind yourself from the stress of modern living. This treatment begins with a Balinese massage. After enhancing the relaxation of your muscle, the skin is exfoliated with a choice of body scrub and finished with Cleopatra''s rose milk Bath.', 990000, 'IDR', 1), ('Facial', 'Ageless Radiance Facial (90 min)', 'Facial combining advanced technologies to tighten and rejuvenate skin.', 1490000, 'IDR', 0), ('Facial', 'Collagen Booster Facial by Dermalogica (90 min)', 'Facial that boosts collagen renewal and revitalizes skin cells.', 1290000, 'IDR', 1), ('Facial', 'Firming & Resurfacing Facial by Dermalogica (90 min)', 'Experience to restore vitality and refresh skin appearance.', 1190000, 'IDR', 2), ('Facial', 'Hydra Glow Facial (75 min)', 'Designed to deeply clean and pump nutrients into the skin.', 850000, 'IDR', 3), ('Facial', 'Glow and Go Facial (45 min)', 'Rapid repair solution to restore skin glow.', 590000, 'IDR', 4), ('Facial', 'Luminous Facial (75 min)', 'Refreshing boost for skin with deep cleanse and hydration.', 850000, 'IDR', 5), ('Facial', 'Calming Oxygen Facial (75 min)', 'Quenching treatment for dehydrated and sun-damaged skin.', 850000, 'IDR', 6), ('Acne Treatment', 'Triple Action Acne Care by Dermalogica (90 min)', 'Treatment designed for acne-prone skin and minimizing inflammation.', 1290000, 'IDR', 0), ('Acne Treatment', 'Acne & Blemish Facial by Dermalogica (75 min)', 'Facial to banish blemishes and balance oil production.', 850000, 'IDR', 1), ('Body Wrap', 'Purifying Coconut Body Wrap (30 min)', 'Widely known as the essential part of Balinese wellness, the coconut mask gives your skin the benefit of antioxidants to destress along moisturize it. Enjoy a heavenly scalp massage while your body is polished in the body wrap.', 290000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'parinaspa.com' and status = 'active' and publication_status = 'published' and category in ('spa', 'beauty', 'yoga', 'fitness') order by case category when 'spa' then 0 when 'beauty' then 1 else 2 end, slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Parina Spa treatment prices',
         coalesce((select max(mx.version) from menus mx where mx.venue_slug = t.slug), 0) + 1,
         'draft', 'partial', 'https://parinaspa.com/', 'Official Parina Spa price list',
         '2026-08-25T05:28:30+00:00'::timestamptz, null, '2026-11-23T05:28:30+00:00'::timestamptz, '2d2dd33eccbfe904960811be29128ddb224c1401c22d9c2ffc579d00586ea9d2', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug
                    and x.status in ('source_snapshot', 'published'))
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Other', 0), ('Balinese Massage', 1), ('Deep Tissue', 2), ('Facial', 3)) as s(name, pos)
  returning id, name
)
