join (values ('Balinese Massage', 'TRADITIONAL BALINESE MASSAGE (60 min)', 'Immerse yourself in the calming rhythms of Bali with this signature treatment. A harmonious blend of acupressure, deep tissue, and traditional Balinese techniques to soothe tension and restore vitality.', 290000, 'IDR', 0), ('Body Scrub', 'BODY SCRUB (120 min)', 'Refresh your skin with a blend of turmeric, cinnamon, nutmeg, and Balinese rice. Ideal for prepping your skin before sun exposure or rejuvenating after a long journey.', 525000, 'IDR', 0), ('Body Scrub', 'CENTELLA ASIATICA SCRUBS (105 min)', 'The scrubs is crafted from a blend of five key natural ingredient, centella known as gotu kola, this herb supports skin repair and stimulates collagen production, helping to improve skin elasticity.', 450000, 'IDR', 1), ('Body Scrub', 'MORINGA SCRUBS (105 min)', 'Traditional body scrub that emphasizes natural ingredient with no added chemicals. Moringa provides antioxidants and essential nutrients to nourish the skin.', 450000, 'IDR', 2), ('Body Scrub', 'COCONUT SCRUB (105 min)', 'A coconut is a natural exfoliating skincare product made from ground coconut shell good for nourishing and antioxidant.', 450000, 'IDR', 3), ('Body Scrub', 'COFFEE SCRUB (105 min)', 'A coffee scrub is a skincare product made by combining ground coffee beans with ingredients like oils, coconut, olive, and salts.', 450000, 'IDR', 4), ('Aromatherapy', 'AROMATHERAPY MASSAGE (60 min)', 'Aromatherapy massage is a relaxing treatment using essential oils to reduce stress, improve circulation, and refresh the body and mind.', 325000, 'IDR', 0), ('Balinese Boreh', 'BOREH BALI HERBAL BATH (120 min)', 'A healing treatment using traditional Balinese Boreh spice wraps to alleviate tension, improve circulation, and detoxify the body. Followed by an herbal bath with lemongrass and betel leaves for complete rejuvenation.', 550000, 'IDR', 0), ('Traditional Massage', 'COMBINATION MASSAGE (60 min)', 'Unwind with a personalized fusion of Balinese-style reflexology, acupressure, and the flowing movements of Lomi Lomi. Perfect for total relaxation and stress relief.', 300000, 'IDR', 0), ('Traditional Massage', 'TENSION RELIEF MASSAGE (30 min)', 'Say goodbye to stress and tension as our therapists focus on your shoulders, back, and neck, leaving you feeling lighter and completely relaxed.', 200000, 'IDR', 1), ('Traditional Massage', 'GOOD KARMA MASSAGE (60 min)', 'Experience the extraordinary sensation of four hands working in perfect harmony. Two therapists will melt away your stress with synchronized movements, awakening your energy, and creating a deep sense of calm.', 550000, 'IDR', 2), ('Traditional Massage', 'BAMBOO MASSAGE (60 min)', 'Pamper your feet with this soothing treatment that promotes circulation, eliminates toxins, and revitalizes your body.', 375000, 'IDR', 3), ('Traditional Massage', 'FACE MASSAGE (60 min)', 'Face massage is a therapeutic skincare technique using movements like pinching, kneading, and stroking to stimulate blood circulation, relieve tension, and promote collagen production.', 275000, 'IDR', 4), ('Facial', 'HERBAL AROMATIC FACIAL (60 min)', 'Give your face the full, gentle treatment: wash, scrub, and peel, followed by a face massage and a herbal cucumber mask. Finish this treatment with a neck, shoulder, and hand massage.', 250000, 'IDR', 0), ('Facial', 'FACIAL BIOKOS BY ALOE VERA (60 min)', 'Fall in love with your skin again as this facial will refresh your natural beauty back to full bloom.', 390000, 'IDR', 1), ('Facial', 'HERBAL MORINGA FACIAL (60 min)', 'Harness the natural antibacterial and detoxifying power of Moringa to cleanse, brighten, and reduce blemishes. Finish with a soothing hand, neck, and shoulder massage.', 350000, 'IDR', 2), ('Spa Package', 'HONEYMOON PACKAGE (150 min)', 'A perfect romantic retreat for couples. Relish in a traditional Balinese massage, followed by a rejuvenating Moringa facial and a dreamy flower bath. Soothe your senses with herbal teas as you reconnect in total harmony.', 1050000, 'IDR', 0), ('Spa Package', 'TEGAL MESARI ROMANTIC PACKAGE (150 min)', 'A blissful journey for the mind, body, and spirit. Experience the healing power of aromatherapy, combined with a refreshing turmeric scrub and a relaxing facial, leaving you feeling completely renewed.', 1250000, 'IDR', 1), ('Pedicure', 'REGULAR PEDICURE (60 min)', 'Foot Bath, toenail sculpturing, cuticle treatment, feet and lower leg massage, please choose the type of polish to complete your treatment.', 250000, 'IDR', 0), ('Pedicure', 'PEDICURE WITH NAIL GEL (60 min)', 'Foot bath, Cuticle treatment, feet and lower leg massage, and please choose the type of polish with nail beauty gel treatment.', 350000, 'IDR', 1), ('Manicure', 'REGULAR MANICURE (60 min)', 'Hand Bath, nail sculpturing, cuticle treatment, and hand and lower arm massage. Please choose the type of polish to complete your treatment.', 250000, 'IDR', 0), ('Manicure', 'MANICURE WITH NAIL GEL (60 min)', 'Hand bath, cuticle treatment, hand, lower arm massage, and please choose the type of polish with nail beauty gel treatment.', 350000, 'IDR', 1), ('Hot Stone', 'HOT STONE MASSAGE (90 min)', 'A full-body massage enhanced with warm, smooth stones to promote deep relaxation, boost circulation, and soothe tired muscles.', 400000, 'IDR', 0), ('Thai Massage', 'THAI REFLEXIOLOGY MASSAGE (45 min)', 'Pamper your feet with this soothing treatment that promotes circulation, eliminates toxins, and revitalizes your body.', 225000, 'IDR', 0), ('Deep Tissue', 'DEEP TISSUE MASSAGE (60 min)', 'A strong-pressure massage that targets deep muscle layers to release tension, reduce pain, and improve flexibility. Ideal for chronic muscle stiffness and stress relief.', 400000, 'IDR', 0), ('Other', 'HERBAL COMPRESS (90 min)', 'A warm herbal bundle gently applied to the body to relieve muscle tension, improve circulation, and promote deep relaxation, made from natural ingredients such as ginger, lemongrass, turmeric, kaffir lime leaves, pandan leaves, camphor, and selected herbs.', 450000, 'IDR', 0), ('Shiatsu', 'SHIATSU MASSAGE (60 min)', 'Traditional Japanese massage uses finger and palm pressure to relieve tension, improve circulation, and promote deep relaxation.', 450000, 'IDR', 0), ('Hair Styling', 'HAIR WASH (45 min)', 'A hair wash is an essential part of personal hygiene and hair care. It gently cleanses the scalp and hair using water and quality cleansing products to remove dirt, excess oil, sweat, product buildup, and environmental impurities.', 180000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'canggu.tonic.co.id' and status = 'active' and publication_status = 'published' and category in ('spa', 'beauty', 'yoga', 'fitness') order by case category when 'spa' then 0 when 'beauty' then 1 else 2 end, slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Tonic Canggu treatment prices',
         coalesce((select max(mx.version) from menus mx where mx.venue_slug = t.slug), 0) + 1,
         'draft', 'partial', 'https://canggu.tonic.co.id/treatments', 'Official Tonic Canggu price list',
         '2026-08-25T05:28:30+00:00'::timestamptz, null, '2026-11-23T05:28:30+00:00'::timestamptz, '08a0d54565dedd36805c0573140c4f6d460b78448b24a4a80781b8f41a097eec', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug
                    and x.status in ('source_snapshot', 'published'))
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Balinese Massage', 0), ('Traditional Massage', 1), ('Hot Stone', 2), ('Deep Tissue', 3), ('Foot Massage', 4), ('Head Massage', 5), ('Other', 6), ('Javanese Lulur', 7), ('Body Scrub', 8), ('Facial', 9), ('Cream Bath', 10), ('Manicure', 11), ('Pedicure', 12)) as s(name, pos)
  returning id, name
)
