join (values ('Other', 'Floating Breakfast', 'Enjoy breakfast in a different way Breakfast Menu: American Breakfast, Continental Breakfast, Indonesian Breakfast, Indian Breakfast', 250000, 'IDR', 0), ('Other', 'Cooking Class with Market Tour', 'Learn the technique and become familiar with fresh herbs spices and traditional ingredients that make Balinese Food delightfully tasty. Valid for 2 person with 1 hour traditional market tour, cooking class time with our executive chef, lunch and certificate.', 1500000, 'IDR', 1), ('Other', 'Candle Light Dinner', 'Feel the Romantic Candle Light Dinner with flower heart shape decoration on the private pool, candle decoration surrounding the pool & set menu dinner with 2 glasses of local wine.', 1200000, 'IDR', 2), ('Other', 'Flower & Fruit Bath Decoration', 'Feel a different sensation The Fragrance of the flowers and the freshness of the fruits can make you feel more comfortable, the mood more stable and the mind becomes more calm', 250000, 'IDR', 3), ('Couple Massage', 'Sweet Couple Dinner', 'Feel the Romantic Sweet Couple Dinner with full floating flower decoration & flower heart shape decoration on the private pool, candle decoration surrounding the pool & set menu dinner with 1 bottle of local wine.', 1500000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'revivebali.com' and status = 'active' and publication_status = 'published' and category in ('spa', 'beauty', 'yoga', 'fitness') order by case category when 'spa' then 0 when 'beauty' then 1 else 2 end, slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Revive Bali treatment prices',
         coalesce((select max(mx.version) from menus mx where mx.venue_slug = t.slug), 0) + 1,
         'draft', 'partial', 'https://revivebali.com/treatments/', 'Official Revive Bali price list',
         '2026-08-25T05:28:30+00:00'::timestamptz, null, '2026-11-23T05:28:30+00:00'::timestamptz, 'eff36cac016d3dc17b5abbc5a8c0f1d8f33e3db1adda55d3ef09923e54e440e3', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug
                    and x.status in ('source_snapshot', 'published'))
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Balinese Massage', 0), ('Aromatherapy', 1), ('Body Scrub', 2), ('Foot Massage', 3), ('Back Massage', 4), ('Nails', 5), ('Manicure', 6), ('Pedicure', 7), ('Other', 8), ('Hair Treatment', 9)) as s(name, pos)
  returning id, name
)
