insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Lashes', 'Lash Tint', 'Our technician will apply a shield to your lid and brush your lashes onto the shield. The color is then applied to your eyelashes. An eyelash tint is a special dye only used on lashes and brows, that can be completely customized to any color. Lash tints normally last between 4-6 weeks. This will depend on how much you touch your lashes, how often you wash your face, and what kind of cleanser or sk', 230000, 'IDR', 0), ('Lashes', 'Lash Lift with Tint', 'A lash lift curls your natural lashes using a three-step perming process. Results vary depending on your individual lash line. In addition, you will have a semi-permanent dye applied to your lashes for a darker appearance. Lash lifts imitate the impact of an eyelash curler. This makes your lashes look longer and your eyes brighter. Keep your lashes dry and free of oil for the first 24 hours.', 690000, 'IDR', 1), ('Lashes', 'Korean Lash Lift & Tint With Keratin Treatment', 'Elevate your natural beauty with our advanced Korean Lash Lift, a technique we learned in Korea and brought to Bali to offer a higher standard of lash care and results. Using a custom fit shield tailored to your exact eye shape, we create a soft, natural lift that enhances your lashes while keeping them healthy and strong. Finished with a nourishing keratin treatment, lashes are left lifted, gloss', 850000, 'IDR', 2), ('Balinese Massage', '60 Minute Balinese Massage (60 min)', '60 minutes of pure bliss. This traditional Balinese massage blends deep pressure, long flowing strokes, and a little magic to melt away tension and get your energy flowing. Expect aromatic oils, full body relaxation, and major “I-needed-that” vibes. Your nervous system will thank you.', 345000, 'IDR', 0), ('Balinese Massage', '75 Minute Balinese Massage (75 min)', '75 minutes of pure bliss. This traditional Balinese massage blends deep pressure, long flowing strokes, and a little magic to melt away tension and get your energy flowing. Expect aromatic oils, full body relaxation, and major “I-needed-that” vibes. Your nervous system will thank you.', 460000, 'IDR', 1), ('Balinese Massage', '90 Minute Balinese Massage (90 min)', '90 minutes of pure bliss. This traditional Balinese massage blends deep pressure, long flowing strokes, and a little magic to melt away tension and get your energy flowing. Expect aromatic oils, full body relaxation, and major “I-needed-that” vibes. Your nervous system will thank you.', 540000, 'IDR', 2), ('Balinese Massage', '60 Min Red Light Full Body Balinese Massage (60 min)', 'Our Balinese massage meets the healing glow of red light therapy for a full body reset. Designed to release tension, calm the mind, and restore balance from the inside out, it’s the kind of stillness your body will thank you for. Red light therapy helps boost circulation, reduce inflammation, and support cellular repair, allowing your body to recover more deeply while enhancing the natural benefit', 630000, 'IDR', 3), ('Deep Tissue', '60 Minute Deep Tissue Massage (60 min)', 'Our 60 minute Deep Tissue Massage is for the ones who need more than a light rub and a prayer. Using slow, focused pressure, we get into the muscles that hold all your stress, tension, and “I’ve been sitting at my laptop too long” energy. It’s deeper, stronger, and designed to actually fix things, not just relax you (though you’ll get plenty of that, too). Walk out feeling lighter, looser, and lik', 450000, 'IDR', 0), ('Deep Tissue', '90 Minute Deep Tissue Massage (90 min)', 'The 90 minute version is for when your body needs more, more time, more release, more everything. This treatment lets our therapists go deeper (literally), giving your muscles the kind of focused attention they’ve been begging for. Think tension melting, knots disappearing, and a whole new level of relaxation. If you want that fully reset, float out the door feeling, this is the one.', 575000, 'IDR', 1), ('Deep Tissue', '90 Minute Deep Stretch & Deep Tissue Massage (90 min)', 'The perfect treatment for anyone who’s feeling tight, tired, or fresh off a long flight. This session blends assisted stretching with deep tissue massage to open up the body, release tension, and get your circulation moving again. It targets stiff hips, tight shoulders, sore lower back, all the spots that need a little extra love. You’ll walk out feeling looser, lighter, and like your body finally', 650000, 'IDR', 2), ('Pregnancy Massage', '60 Min Pregnancy Massage (60 min)', 'A gentle, supportive massage designed to ease common pregnancy discomforts such as tension in the lower back, hips, shoulders, and legs. This treatment helps improve circulation, reduce fluid retention, and calm the nervous system while keeping both mother and baby fully supported with safe pregnancy positioning throughout. We use only pure coconut oil, free from fragrance or added ingredients, ma', 350000, 'IDR', 0), ('Brows', 'Brow Tinting', 'Eyebrow tinting is the process of applying semi-permanent dye to enhance, shape, darken, and define your brows. Not only can eyebrow tinting darken every hair, but it can also target lighter, baby hairs and peach fuzz, revealing the full potential of your brows. With customizable colours, you can achieve the perfect look to suit your personal and desired style.', 230000, 'IDR', 0), ('Brows', 'Brow Lamination', 'Brow Lamination is a three part process that enhances the appearance of the eyebrows by boosting the brow hairs, resulting in a fuller and more personalized brow look. With little aftercare required, Brow Lamination is a convenient and long-lasting solution for those looking to achieve a flawless brow shape. A custom tint is then added to give even more definition to the lamination. This service i', 690000, 'IDR', 1), ('Waxing', 'Brow Waxing', 'Our brow waxing service is a quick and easy way to maintain the appearance of your eyebrows. Each service begins with brow mapping to ensure the perfect shape for your unique features. Our technicians use both soft and hard wax to protect your skin and provide the best possible results.', 230000, 'IDR', 0), ('Waxing', 'Brow Tinting, Shaping & Waxing', 'Want the whole package? We''ve customized a brow package so you don''t need to stress. Our brow package of tinting, shaping and waxing has all your brow needs covered. Our technicians will start by customizing a tint that goes perfectly with the colour of your natural brow, if you prefer a more specific outcome, just let them know. They will then map out your brows, sculpting them into the best poss', 402000, 'IDR', 1), ('Facial', 'Refresh - Facial (60 min)', 'Give your skin a fresh start with our most basic facial. This 60 minute facial starts includes double cleanse, steam, exfoliation, facial massage and custom face mask, followed by your custom aftercare.', 690000, 'IDR', 0), ('Facial', 'Korean Sculpt & Glow Facial (60 min)', 'Our Korean Facial is a sculpt and glow reset, a 60 minute lifting ritual designed to de puff, contour, and wake up the face in all the right places. Using meridian activation, gua sha sculpting, and cooling scalp therapy, this treatment supports lymphatic drainage, releases tension, boosts circulation, and leaves skin lifted, brighter, and glowing. Think sculpted jawline, calm nervous system, and ', 1200000, 'IDR', 1), ('Facial', 'Jet Lagged - Facial (90 min)', 'Come and indulge in our 90 minute, ultimate relaxation facial. This facial includes all the basics as well as some super relaxing add ons. This customized facial will not only leave you with a fresh face, but you''ll also leave incredibly relaxed like you''ve just woken up from a dream. Included in this facial, double cleanse, steam, physical exfoliation, enzyme treatment, high frequency, facial mas', 977000, 'IDR', 2), ('Facial', 'Fire & Ice Facial by Is Clinical', 'Experience our unique facial suitable for all skin types. Includes all the basics + ''Fire'' masque with glycolic acid, retinol, and antioxidants, followed by the rejuvenating ''Ice'' mask with hyaluronic acid and green tea. Leaves your skin repaired, refreshed, and glowing. This facial includes, double cleanse, steam, extractions, fire and ice masks, high-frequency, facial and neck & decollate massag', 1200000, 'IDR', 3), ('Facial', 'The Back Facial', 'A back facial is a rejuvenating spa treatment that starts with a thorough double cleansing to remove impurities and excess oils. The next step involves a gentle steaming of the back to open pores and prepare the skin for exfoliation. During exfoliation, dead skin cells are sloughed away, leaving the skin smoother and more radiant. An enzyme treatment is then applied to further refine the skin''s te', 862000, 'IDR', 4), ('Other', 'Dermaplaning', 'Discover the transformative power of Dermaplaning, also known as Epidermal Levelling, at Salty Face Bali. This deep physical exfoliation technique is designed to slough off built-up dead skin cells and debris on the skin''s surface, paving the way for enhanced product absorption into the follicles. Using a medical-grade blade, Dermaplaning effectively removes 21 to 28 days'' worth of buildup, leavin', 1380000, 'IDR', 0), ('Other', 'Skin Glow', 'Discover the transformative power of Dermaplaning, this deep physical exfoliation technique is designed to slough off built-up dead skin cells and debris on the skin''s surface, paving the way for enhanced product absorption into the follicles. After dermaplaning is completed is it then followed by the famous Fire & Ice treatment by ISClinical. This is a extra intensive and exfoliating treatment an', 2000000, 'IDR', 1), ('Other', 'Microneedling', 'Microneedling is a minimally invasive procedure that uses fine needles to create controlled skin punctures, stimulating collagen production and skin rejuvenation. The process involves numbing the skin, then using a device to create micro-injuries. This results in improved skin texture, reduced scars, and better product absorption. Afterward, patients may experience temporary redness and swelling, ', 1720000, 'IDR', 2), ('Other', 'Underarms', 'Underarm area', 172000, 'IDR', 3), ('Other', 'Bikini Area', 'Everything that shows while you''re wearing your best bikini bottoms or undies.', 230000, 'IDR', 4), ('Other', 'Brazilian', 'Absolutely everything from front to back!', 345000, 'IDR', 5), ('Other', 'Full Arms', 'Knuckles, hands, lower and upper arms.', 575000, 'IDR', 6), ('Other', 'Half Legs', 'Toes, feet, calves and knees.', 460000, 'IDR', 7), ('Other', 'Full Legs', 'Toes, feet, calves, knees and thighs.', 690000, 'IDR', 8), ('Other', 'Underarms & Bikini', 'Underarm area and Bikini Area', 322000, 'IDR', 9), ('Other', 'Brazilian & Underarm', 'Brazilian and Underarms', 465000, 'IDR', 10), ('Other', 'Full Arms & Legs', 'Knuckles, hands, full arms, toes, feet, calves, thighs.', 1100000, 'IDR', 11), ('Other', 'Brazilian, Full Arms & Legs', 'Brazilian, Knuckles, hands, full arms, toes, feet, calves, thighs.', 1300000, 'IDR', 12)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

