join (values ('Other', 'The Resting Koala (60 min)', 'Indulge in our signature full-body massage, inspired by the laid-back energy of Bali. This treatment blends soothing, warm aromatherapy oils, carefully selected for their relaxing qualities, to lull you into a state of deep calm. Let our skilled therapists melt away tension from head to toe, leaving you feeling renewed and blissfully at peace.', 320000, 'IDR', 0), ('Other', 'The Resting Koala (90 min)', 'Indulge in our signature full-body massage, inspired by the laid-back energy of Bali. This treatment blends soothing, warm aromatherapy oils.', 420000, 'IDR', 1), ('Other', 'The Journey (120 min)', 'Begin your journey of relaxation with a soothing foot ritual, grounding you in tranquility before transitioning into an indulgent full-body massage.', 600000, 'IDR', 2), ('Other', 'The Athlete (60 min)', 'Crafted for active souls, this deep tissue massage targets key muscle groups to alleviate soreness and improve mobility.', 390000, 'IDR', 3), ('Other', 'The Athlete (90 min)', 'Crafted for active souls, this deep tissue massage targets key muscle groups to alleviate soreness and improve mobility.', 520000, 'IDR', 4), ('Other', 'The Sun Soother (60 min)', 'Soothe and refresh sun-kissed skin with this cooling aloe vera wrap. Combined with a gentle face and head massage.', 400000, 'IDR', 5), ('Other', 'The Glow (60 min)', 'A calming ritual that begins with a back massage to melt away tension, followed by facial acupressure to restore circulation and glow.', 400000, 'IDR', 6), ('Other', 'The Blooming Koala (90 min)', 'A calming ritual that begins with a back massage to melt away tension, followed by facial acupressure to restore circulation and glow.', 850000, 'IDR', 7), ('Other', 'The Blooming Koala (120 min)', 'A calming ritual that begins with a back massage to melt away tension, followed by facial acupressure to restore circulation and glow.', 1050000, 'IDR', 8), ('Foot Massage', 'The Foot Release (30 min)', 'Start with a gentle foot ritual to prepare your feet for this soothing reflexology-inspired massage. By working through pressure points, this treatment relieves tension and restores balance, grounding you and leaving your feet feeling refreshed and rejuvenated.', 160000, 'IDR', 0), ('Foot Massage', 'The Foot Release (60 min)', 'Start with a gentle foot ritual to prepare your feet for this soothing reflexology-inspired massage.', 210000, 'IDR', 1), ('Foot Massage', 'Foot Scrub (15 min)', 'A revitalizing exfoliation using our homemade Himalayan salt infused with peppermint essential oil.', 110000, 'IDR', 2), ('Balinese Massage', 'The Balinese (60 min)', 'Immerse yourself in the timeless healing of Bal’s traditional massage. With rhythmic strokes, gentle stretches, and acupressure, this treatment invites you to unwind and harmonize body and mind, bringing a deep sense of balance and tranquility.', 300000, 'IDR', 0), ('Balinese Massage', 'The Balinese (90 min)', 'Immerse yourself in the timeless healing of Bal’s traditional massage.', 400000, 'IDR', 1), ('Scalp Treatment', 'Dry Scalp Massage (15 min)', 'Tension melts away with this soothing head massage.', 110000, 'IDR', 0), ('Facial', 'Facial Massage & Aloe Vera Mask (15 min)', 'A pressure-point facial massage for a lifted glow, finished with a freshly blended, cooling aloe vera mask prepared during your treatment.', 110000, 'IDR', 0), ('Spa Package', 'Body Polish & Shower Ritual (30 min)', 'Tension melts away with this soothing head massage.', 180000, 'IDR', 0), ('Spa Package', 'Shower Ritual (15 min)', 'Elevate your treatment with access to our private shower facilities, complete with premium amenities and plush towels.', 50000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

