join (values ('Other', 'BUFF (40 min)', 'Clean, shape, buff and groom cuticles. Finish with a conditioning massage for healthy, natural-looking nails.', 195000, 'IDR', 0), ('Other', 'POLISH (60 min)', 'Clean, shape and groom cuticles. Finish with a conditioning massage and your choice of OPI nail polish or OPI Gel Polish.', 255000, 'IDR', 1), ('Other', 'FRENCH (75 min)', 'Clean, shape and groom cuticles. Finish with a conditioning massage and classic French polish or French Gel Polish.', 315000, 'IDR', 2), ('Other', 'EXPRESS (40 min)', 'Quick clean, shape and polish. Perfect for beautifully groomed nails on the go.', 195000, 'IDR', 3), ('Other', 'POLISH CHANGE (20 min)', 'Remove existing polish and apply your choice of OPI nail polish or OPI Gel Polish.', 135000, 'IDR', 4), ('Other', 'FRENCH POLISH CHANGE (20 min)', 'Remove existing polish and apply a classic French polish or French Gel Polish.', 195000, 'IDR', 5), ('Other', 'POLISH REMOVAL', 'Safe removal of existing gel polish or hard gel.', 120000, 'IDR', 6), ('Other', 'The Whole Shebang (210 min)', 'The ultimate treat that induces that lost in paradise feeling, however when you return to reality you will be feeling and looking a whole lot better than before. Totally indulgent combo of our Classic Massage, the Thank Me Later Facial and a Mani-Pedi will leave you feeling all round awesome.', 1150000, 'IDR', 7), ('Other', 'Back on the Wagon (100 min)', 'Absolve yourself of your ''sins'' and make it all ok again with this purifying combination of Coconut Dream Body Scrub Treatment and Chili Ultrasonic Detox Treatment. Great as an add on to detox retreat program.', 675000, 'IDR', 8), ('Nails', 'CHILDREN’S NAILS', 'Nail shaping and OPI polish for little hands and feet.', 195000, 'IDR', 0), ('Nail Art', 'NAIL ART', 'Custom nail art including flowers, dots, patterns & creative designs.', 30000, 'IDR', 0), ('Neck & Shoulder', 'Back, Neck & Shoulder Recovery Massage (30 min)', 'This targeted back, neck, and shoulder massage relieves tension, reduces stress, and restores mobility.', 275000, 'IDR', 0), ('Balinese Massage', 'Classic Balinese Massage (60 min)', 'Experience traditional Balinese massage combining therapeutic techniques with long, flowing strokes to relieve muscle tension, improve circulation, and promote deep relaxation.', 475000, 'IDR', 0), ('Traditional Massage', 'Posture & Tension Release Massage (75 min)', 'The ultimate antidote to too many hours at the laptop.', 650000, 'IDR', 0), ('Shiatsu', 'Shiatsu Massage (60 min)', 'Keep your comfortable clothes on! This traditional Japanese Shiatsu massage uses finger, palm, and thumb pressure on acupressure points along the body’s meridian pathways.', 495000, 'IDR', 0), ('Hot Stone', 'Hot Stone Massage (90 min)', 'This blissful treatment combines the therapeutic warmth of heated stones with flowing massage techniques.', 825000, 'IDR', 0), ('Detox Treatment', 'Chilli & Sound Wave Detox Treatment (90 min)', 'This intensive body treatment combines manual lymphatic drainage massage.', 1150000, 'IDR', 0), ('Body Scrub', 'Coconut Dream Body Scrub (30 min)', 'This tropical body scrub combines our signature coconut oil blend with mineral-rich sea salt.', 450000, 'IDR', 0), ('Body Scrub', 'Magic Glove Korean Body Scrub (45 min)', 'Experience a traditional Korean-style body scrub designed to remove dead skin cells.', 500000, 'IDR', 1), ('Body Treatment', 'Sunburn Relief Fresh Coconut Body Treatment (45 min)', 'Created for surfers, beach lovers, and skin exposed to a little too much sun.', 450000, 'IDR', 0), ('Facial', 'Smooth and Clear Back Facial (60 min)', 'Treat breakouts, congestion, or simply indulge in some self-care with our deep-cleansing back facial.', 475000, 'IDR', 0), ('Facial', 'Sensitive Skin Glow Facial (45 min)', 'A refreshing express facial designed for sensitive skin and those short on time.', 735000, 'IDR', 1), ('Facial', 'Supernova Glow Facial (90 min)', 'Our signature facial for normal skin, combining a 5-phase cleansing ritual, gentle exfoliation.', 895000, 'IDR', 2), ('Facial', 'Daddy-O Men’s Facial (60 min)', 'Designed specifically for men’s skin, this deep-cleansing facial combines gentle exfoliation.', 825000, 'IDR', 3), ('Facial', 'Kobido Japanese Facial Massage (60 min)', 'Experience the timeless art of Kobido, a traditional Japanese facial massage.', 895000, 'IDR', 4), ('Facial', 'Cadillac Luxury Anti-Ageing Facial (90 min)', 'Our ultimate luxury facial combines premium Yon-Ka skincare with Japanese-inspired Shiatsu acupressure massage techniques.', 1400000, 'IDR', 5), ('Acne Treatment', 'Revamp Acne & Clarifying Facial (75 min)', 'A deep-cleansing facial designed for acne-prone and congested skin.', 895000, 'IDR', 0), ('Hydrating Facial', 'Ivy Leaguer Hydration & Fine Line Facial (75 min)', 'An intensely nourishing facial designed for dry, dehydrated skin.', 1045000, 'IDR', 0), ('Head Massage', 'Japanese Head Spa – Scalp Detox & Renewal (75 min)', 'Experience our Japanese Head Spa at FRESH Bali in Ubud, Canggu, and Uluwatu.', 850000, 'IDR', 0), ('Head Massage', 'Japanese Head Spa & Kobido Facial (90 min)', 'Experience our Japanese Head Spa and Kobido Facial at FRESH in Ubud, Canggu, and Uluwatu.', 1050000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'spashell.id' and status = 'active' and publication_status = 'published' and category in ('spa', 'beauty', 'yoga', 'fitness') order by case category when 'spa' then 0 when 'beauty' then 1 else 2 end, slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Spa Shell treatment prices',
         coalesce((select max(mx.version) from menus mx where mx.venue_slug = t.slug), 0) + 1,
         'draft', 'partial', 'https://spashell.id/', 'Official Spa Shell price list',
         '2026-08-25T05:28:30+00:00'::timestamptz, null, '2026-11-23T05:28:30+00:00'::timestamptz, 'bc164f31c99336a75dd3d88d6062cad2809a4db726d4e22e32f00320d1363a51', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug
                    and x.status in ('source_snapshot', 'published'))
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Balinese Massage', 0), ('Deep Tissue', 1), ('Other', 2), ('Reflexology', 3), ('Aromatherapy', 4), ('Sports Massage', 5), ('Body Treatment', 6), ('Lymphatic Massage', 7), ('Hot Stone', 8), ('Traditional Massage', 9)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Balinese Massage', 'Balinese Massage (60 min)', 'A traditional full-body therapy combining gentle stretches, acupressure, and our signature oil blend to stimulate the flow of blood and oxygen.', 220000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue Massage (60 min)', 'A therapeutic treatment focusing on the deeper layers of muscle tissue. We use firm pressure to release chronic muscle tension and knots.', 260000, 'IDR', 0), ('Other', 'Stress Relief Express (30 min)', 'A focused treatment targeting high-tension areas in the back, neck, and shoulders to quickly relieve stiffness.', 110000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (30 min)', 'Ancient healing therapy applying pressure to specific points on the feet that correspond to different body organs to restore balance.', 100000, 'IDR', 0), ('Aromatherapy', 'Warm Aromatherapy Massage (60 min)', 'A luxurious ritual using Pure Sweet Almond Oil blended with Organic Essential Oils.', 260000, 'IDR', 0), ('Sports Massage', 'Sports Massage (60 min)', 'Focuses on areas of the body that are overused and stressed from repetitive movements.', 300000, 'IDR', 0), ('Body Treatment', 'Anti-Cellulite / Slimming Massage (60 min)', 'An intensive, vigorous technique aimed at breaking down fat deposits and improving blood circulation.', 300000, 'IDR', 0), ('Lymphatic Massage', 'Lymphatic Drainage Massage (60 min)', 'A gentle, rhythmic massage technique designed to stimulate the lymphatic system.', 300000, 'IDR', 0), ('Hot Stone', 'Hot Stone Massage (90 min)', 'Smooth, heated volcanic basalt stones are used as an extension of the therapist’s hands.', 450000, 'IDR', 0), ('Traditional Massage', 'Herbal Compress Massage (90 min)', 'Warm steamed cotton pouches filled with healing herbs.', 450000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

